  body { display: flex; justify-content: center; align-items: flex-start; padding: calc(14px + env(safe-area-inset-top)) 8px calc(14px + env(safe-area-inset-bottom)); }
  .unit { width: 100%; max-width: 640px; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 14px; }
