  .mode-row { display: flex; gap: 6px; }
  .mode-btn { background: var(--surface-2); border: 1px solid var(--border); color: var(--text-dim); font-family: var(--mono); font-size: 11px; font-weight: 700; letter-spacing: 0.08em; padding: 12px 14px; border-radius: 999px; cursor: pointer; }
