  .about { font-size: 11px; color: var(--text-dim); margin-top: 8px; line-height: 1.7; }
  .about b { color: var(--cyan); }
  .radio-group { margin-bottom: 6px; }
  .radio-group .field-label { margin-bottom: 4px; }
  .radio-row { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--text); padding: 10px 10px; border: 1px solid var(--border); border-radius: 12px; margin-bottom: 4px; cursor: pointer; background: var(--surface-2); }
  .radio-row:hover { border-color: var(--amber); }
  .radio-row input { accent-color: var(--amber); margin: 0; }
  .radio-row span { word-break: break-all; }

  /* API key ring, one panel per provider */
  .kr-panel { border: 1px solid var(--border); border-radius: 12px; padding: 10px; margin-bottom: 10px; background: var(--surface-2); }
  .kr-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; }
  .kr-title { font-size: 11px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--amber-hi, var(--amber)); }
  .kr-count { font-size: 10px; color: var(--text-dim); }
  .kr-empty { font-size: 11px; color: var(--text-dim); padding: 6px 0; }
  .kr-row { display: flex; align-items: center; gap: 8px; padding: 8px 6px; border-bottom: 1px solid var(--border); }
  .kr-row:last-of-type { border-bottom: none; }
  .kr-row input[type=radio] { accent-color: var(--amber); margin: 0; flex: 0 0 auto; }
  .kr-info { flex: 1; min-width: 0; }
  .kr-mask { font-size: 12px; word-break: break-all; }
  .kr-meta { font-size: 10px; color: var(--text-dim); margin-top: 2px; }
  .kr-badge { font-size: 9px; font-weight: 700; letter-spacing: 0.05em; padding: 2px 6px; border-radius: 999px; text-transform: uppercase; display: inline-flex; align-items: center; gap: 3px; }
  .kr-badge .kr-glyph { font-size: 10px; }
  .kr-badge.live { color: var(--green); background: rgba(34, 197, 94, 0.14); }
  .kr-badge.new { color: var(--text-dim); background: var(--surface); }
  .kr-badge.dead { color: var(--red); background: rgba(239, 68, 68, 0.14); }
  .kr-badge.nocredit { color: var(--amber); background: rgba(245, 158, 11, 0.14); }
  .kr-badge.cool { color: var(--amber); background: rgba(245, 158, 11, 0.14); }
  .kr-live { font-size: 10px; color: var(--text-dim); min-height: 14px; margin: 2px 0 4px; }
  .kr-live .kr-glyph.testing { animation: krSpin 1.2s steps(8) infinite; display: inline-block; }
  .kr-live .kr-glyph.live { color: var(--green); }
  .kr-live .kr-glyph.dead { color: var(--red); }
  .kr-live .kr-glyph.nocredit, .kr-live .kr-glyph.cool { color: var(--amber); }
  .kr-live .kr-glyph.unclear { color: var(--text-dim); }
  @keyframes krSpin { from { opacity: 1; } to { opacity: 0.3; } }
  .kr-verbatim { color: var(--green); }
  .kr-row-actions { display: flex; gap: 4px; flex: 0 0 auto; }
  .kr-mini-btn { background: var(--surface); border: 1px solid var(--border); color: var(--text-dim); font-family: var(--mono); font-size: 10px; padding: 6px 8px; border-radius: 999px; cursor: pointer; }
  .kr-mini-btn:hover { border-color: var(--amber); color: var(--amber); }
  .kr-mini-btn.danger:hover { border-color: var(--red); color: var(--red); }
  .kr-import { margin-top: 6px; }
  .kr-import textarea { width: 100%; min-height: 60px; background: var(--bg); border: 1px solid var(--border); border-radius: 8px; color: var(--text); font-family: var(--mono); font-size: 11px; padding: 8px; margin-bottom: 6px; }
  .kr-import-row { display: flex; gap: 4px; }
  .kr-import-row .small-btn { flex: 1; text-align: center; }
</style>
</head>
<body>
<div class="unit">
  <header>
    <div>
      <div class="mode-row" role="group" aria-label="recording mode">
        <button type="button" class="mode-btn" id="modeMulti" data-mode="multi" title="every recording is added under the last one, tap again to start fresh">MULTIPLE</button>
        <button type="button" class="mode-btn" id="modeSingle" data-mode="single" title="every recording replaces the text, tap again to start fresh">SINGLE</button>
      </div>
    </div>
    <button class="gear" id="gearBtn" title="settings" aria-label="settings">&#9881;</button>
  </header>

  <div class="tabs" role="tablist">
    <button class="tab-btn active" id="recPill" data-tab="rec"><span class="hot-r" id="recPillLabel">REC</span></button>
    <button class="tab-btn" data-tab="transcribe">transcribe</button>
  </div>

  <div class="meter idle" id="meter" aria-hidden="true"></div>

  <!-- SHARED SETTINGS, same buttons and position on REC and TRANSCRIBE, always at the top of whichever of those two tabs is open -->
  <div class="shared-settings" id="sharedSettings">
    <div class="row" id="langRow" role="group" aria-label="language">
      <button type="button" class="lang-btn" data-lang="hr">HR</button>
      <button type="button" class="lang-btn" data-lang="en">EN</button>
      <button type="button" class="lang-btn" data-lang="auto">AUTO</button>
    </div>
  </div>

  <!-- REC -->
  <div class="tab active" id="tab-rec">
    <div class="rec-clock" id="recClock">00:00<span class="ms">.0</span></div>
    <div class="rec-state" id="recState"></div>
    <canvas class="scope" id="recScope" width="600" height="150"></canvas>
    <div class="rec-controls">
      <button type="button" class="rec-cancel-btn" id="recCancelBtn" aria-label="cancel" title="cancel and throw this away" disabled>&#10005;</button>
    </div>
    <div class="status" id="recStatus"></div>
    <div class="session-line" id="sessionLine">session empty</div>
    <div class="mode-hint" id="modeHint"></div>
    <button type="button" class="transcribe-btn" id="recTranscribeBtn" disabled>TRANSCRIBE ALL PARTS</button>
  </div>

  <!-- TRANSCRIBE -->
  <div class="tab" id="tab-transcribe">
    <label class="drop" id="drop" for="audioInput">
      <span id="dropLabel">CHOOSE FILE</span>
      <input type="file" id="audioInput" accept="audio/*,video/*">
    </label>

    <button type="button" class="transcribe-btn" id="transcribeBtn" disabled>TRANSCRIBE</button>
    <div class="status" id="status"></div>
    <div class="box-tools has-copy">
      <button type="button" class="small-btn" data-boxact="paste" data-target="transcript">paste</button>
      <button type="button" class="copy-cp" id="copyBtn" aria-label="copy" title="copy">CP</button>
      <button type="button" class="small-btn" data-boxact="clear" data-target="transcript">clear</button>
    </div>
    <div class="transcript-wrap">
      <textarea id="transcript" placeholder="transcript will appear here" spellcheck="false"></textarea>
    </div>

    <div class="rec-row">
      <button type="button" class="transcribe-btn" id="grammarBtn">GRAMMAR</button>
      <button type="button" class="transcribe-btn" id="reshapeBtn">RE-SHAPE</button>
    </div>
    <div class="status" id="grammarStatus"></div>
    <div class="box-tools has-copy">
      <button type="button" class="small-btn" data-boxact="paste" data-target="transcriptCorr">paste</button>
      <button type="button" class="copy-cp" id="copyCorrBtn" aria-label="copy" title="copy">CP</button>
      <button type="button" class="small-btn" data-boxact="clear" data-target="transcriptCorr">clear</button>
    </div>
    <div class="transcript-wrap">
      <textarea id="transcriptCorr" placeholder="corrected text will appear here" spellcheck="false"></textarea>
    </div>

    <div class="claude-usage" id="claudeLevelLabel">engagement level</div>
    <div class="row claude-effort-row" id="claudeRow">
      <button type="button" class="lang-btn claude-effort" data-effort="low" id="claude-low">Opus Low</button>
      <button type="button" class="lang-btn claude-effort" data-effort="medium" id="claude-medium">Opus Medium</button>
      <button type="button" class="lang-btn claude-effort" data-effort="high" id="claude-high">Opus High</button>
    </div>
    <div class="status" id="claudeStatus"></div>
    <div class="claude-usage" id="claudeUsage">Claude API  ·  spent $0.0000  ·  left $5.0000</div>
  </div>

  <!-- ARH -->  <!-- ARH -->
  <div class="tab" id="tab-arh">
    <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; margin-bottom:8px;">
      <div class="status" id="arhStatus" style="margin:0; min-height:0;">archive</div>
      <button type="button" class="small-btn danger" id="arhDeleteAllBtn">delete all</button>
    </div>
    <div id="arhList"><div class="arh-empty">no recordings yet</div></div>
  </div>

  <!-- TRANSLATE -->
  <div class="tab" id="tab-translate">
    <div class="row" id="transFromRow" role="group" aria-label="from language">
      <button type="button" class="lang-btn tl-from" data-lang="hr">HR</button>
      <button type="button" class="lang-btn tl-from" data-lang="en">EN</button>
      <button type="button" class="lang-btn tl-from" data-lang="auto">AUTO</button>
