    <div class="box-tools">
      <button type="button" class="small-btn" data-boxact="paste" data-target="transSrc">paste</button>
      <button type="button" class="small-btn" data-boxact="clear" data-target="transSrc">clear</button>
    </div>
    <textarea id="transSrc" style="min-height:150px;" placeholder="text to translate" spellcheck="false"></textarea>
    <button type="button" class="transcribe-btn" id="translateBtn">TRANSLATE</button>
    <div class="status" id="transStatus"></div>
    <div class="row" id="transToRow" role="group" aria-label="to language">
      <button type="button" class="lang-btn tl-to" data-lang="hr">HR</button>
      <button type="button" class="lang-btn tl-to" data-lang="en">EN</button>
      <button type="button" class="lang-btn tl-to" data-lang="auto">AUTO</button>
    </div>
    <div class="box-tools has-copy">
      <button type="button" class="small-btn" data-boxact="paste" data-target="transOut">paste</button>
      <button type="button" class="copy-cp" id="copyTransBtn" aria-label="copy" title="copy">CP</button>
      <button type="button" class="small-btn" data-boxact="clear" data-target="transOut">clear</button>
    </div>
    <div class="transcript-wrap">
      <textarea id="transOut" placeholder="translation will appear here" spellcheck="false"></textarea>
    </div>
    <label class="field-label">gemini model</label>
    <div class="row" id="transModelList" style="flex-wrap:wrap;"></div>
  </div>

  <!-- QUICK, walkie talkie style, one button, Whisper -->
  <!-- SETTINGS -->
  <div class="tab" id="settingsPanel">
    <div class="rec-settings-label">SETTINGS</div>
    <button class="tab-btn" data-tab="arh">ARCHIVE</button>
    <label class="field-label">engine</label>
    <div class="key-list">
      Gemini, and the model is chosen for you from the ones the account can
      actually reach. There is nothing to pick here and nothing to keep current.
    </div>
    <label class="field-label">api keys</label>
    <div class="key-list">
      The keys are not in this browser. They live in one ring on the server,
      shared with the rest of this app, and the KEYS tab is where they are
      imported, tested and deleted.
    </div>
    <div class="about">
      engine: <b>Gemini, model chosen automatically</b><br>
      keys: <b>the shared ring, in the KEYS tab</b><br>
      file picker: <b>any format ffmpeg can read, optimized before upload</b><br>
      version: <b id="appVersion">v28 (a)</b>
    </div>
  </div>
</div>


<script>
(function () {
  // =========================================================================
  // KEYRING — ported from markoboskoauroville/MAHA_TRANSCRIBE_STREAMLIT
  // ttt/keyring.py. No key is ever hardcoded in this file: every provider's
  // ring lives only in this browser's localStorage, filled in by the person
  // through Settings > api keys, either by pasting a note or picking a file.
  // =========================================================================
  const KR = (() => {
    async function fingerprint(key) {
      const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(key));
      return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('').slice(0, 12);
    }
    function mask(key) {
      const k = (key || '').trim();
      if (k.length <= 10) return k ? k.slice(0, 2) + '\u2026' : '';
      return k.slice(0, 5) + '\u2026' + k.slice(-4);
    }
    function newRing() { return { keys: [], active: 0 }; }

    // first usable key at or after start, wrapping; a rested "cool" key revives itself once its time is up.
    // "nocredit" never self-revives, same as "dead" -- an empty account does not top itself up.
    function pick(ring, start) {
      const keys = ring.keys || []; const n = keys.length;
      if (!n) return null;
      const now = Date.now() / 1000;
      for (let j = 0; j < n; j++) {
        const i = (start + j) % n;
        const k = keys[i];
        if (k.state === 'dead' || k.state === 'nocredit') continue;
        if (k.state === 'cool') {
          if ((k.coolUntil || 0) > now) continue;
          k.state = 'new'; k.lastError = '';
        }
        return i;
      }
      return null;
    }
    function usable(ring) { return (ring.keys || []).some(k => k.state !== 'dead' && k.state !== 'nocredit'); }
    function counts(ring) {
      const now = Date.now() / 1000; let live = 0, dead = 0, cool = 0, nocredit = 0;
      for (const k of (ring.keys || [])) {
        if (k.state === 'dead') dead++;
        else if (k.state === 'nocredit') nocredit++;
        else if (k.state === 'cool' && (k.coolUntil || 0) > now) cool++;
        else live++;
      }
      return { total: (ring.keys || []).length, live, dead, cool, nocredit };
    }

    const URL_RE = /https?:\/\/\S+/g;
    const TOKEN_RE = /[A-Za-z0-9][A-Za-z0-9_.\-]{11,}/g;

    // find every key-shaped token in a piece of messy pasted text, line-aware,
    // and add whichever ones are not already in the ring. Returns how many were new.
    async function importKeys(ring, raw, prefixes, minLen, genericMin) {
      minLen = minLen || 16; genericMin = genericMin || 24; prefixes = prefixes || [];
      const lines = (raw || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
      function tokensOn(line) {
        const cleaned = line.replace(URL_RE, m => prefixes.some(p => m.toLowerCase().includes(p)) ? m : ' ');
        const out = []; let m;
        TOKEN_RE.lastIndex = 0;
        while ((m = TOKEN_RE.exec(cleaned))) {
          const t = m[0].replace(/^[.\-_]+|[.\-_]+$/g, '');
          if (t.length >= 12) out.push(t);
        }
        return out;
      }
      function isPrefixed(tok) {
        const low = tok.toLowerCase();
        return prefixes.length > 0 && prefixes.some(p => low.startsWith(p)) && tok.length >= minLen;
      }
      const perLine = lines.map(tokensOn);
      let found = [];
      perLine.forEach((toks, i) => toks.forEach(tok => { if (isPrefixed(tok)) found.push([tok, i]); }));
      if (!found.length) {
        perLine.forEach((toks, i) => toks.forEach(tok => {
          if (tok.length >= genericMin && /[0-9]/.test(tok) && /[A-Za-z]/.test(tok)) found.push([tok, i]);
        }));
      }
      ring.keys = ring.keys || [];
      const have = new Set(ring.keys.map(k => k.key));
      const seen = new Set(); let added = 0;
      for (const [key, lineIdx] of found) {
        if (seen.has(key) || have.has(key)) continue;
        seen.add(key);
        const label = lineIdx > 0 ? (lines[lineIdx - 1] || '').trim() : '';
        ring.keys.push({
          key, fp: await fingerprint(key), state: 'new', label,
          lastError: '', calls: 0, coolUntil: 0, added: Math.floor(Date.now() / 1000)
        });
        added++;
      }
      return added;
    }

    function markDead(ring, idx, err) { const k = ring.keys[idx]; k.state = 'dead'; k.lastError = err || ''; }
    function markNoCredit(ring, idx, err) { const k = ring.keys[idx]; k.state = 'nocredit'; k.lastError = err || ''; }
    function markCool(ring, idx, err, seconds) {
      const k = ring.keys[idx]; k.state = 'cool'; k.lastError = err || '';
      k.coolUntil = Date.now() / 1000 + (seconds != null ? seconds : 120);
    }
    function markOk(ring, idx) { const k = ring.keys[idx]; k.state = 'new'; k.lastError = ''; k.calls = (k.calls || 0) + 1; }
    function reviveAll(ring) {
      let n = 0;
      for (const k of (ring.keys || [])) {
        if (k.state === 'dead' || k.state === 'nocredit' || k.state === 'cool') { k.state = 'new'; k.lastError = ''; k.coolUntil = 0; n++; }
      }
      return n;
    }
    function reviveOne(ring, idx) { const k = ring.keys[idx]; if (!k) return; k.state = 'new'; k.lastError = ''; k.coolUntil = 0; }
    function deleteOne(ring, idx) {
      ring.keys.splice(idx, 1);
      if (ring.active >= ring.keys.length) ring.active = 0;
    }

    // walk the ring until a key works. attempt(keyStr) resolves to
    // {result, err, kind, wait} where kind is 'ok' | 'dead' | 'nocredit' | 'cool' | 'soft' | 'canceled'.
    // a 'soft' failure is nobody's fault, so it stops immediately instead of burning every key.
    async function rotate(ring, attempt) {
      const keys = ring.keys || []; const n = keys.length;
      if (!n) return { result: null, err: 'no keys yet, add one in settings' };
      let idx = (ring.active || 0) % n;
      let last = '';
      for (let tries = 0; tries < n; tries++) {
        const i = pick(ring, idx);
        if (i === null) break;
        const key = keys[i].key;
        const got = await attempt(key);
        if (got.kind === 'canceled') return { result: null, err: null, canceled: true };
        if (got.kind === 'ok') {
          markOk(ring, i);
          ring.active = i;
          return { result: got.result, err: null, keyIndex: i };
        }
        last = got.err || 'unknown error';
        if (got.kind === 'dead') markDead(ring, i, got.err);
        else if (got.kind === 'nocredit') markNoCredit(ring, i, got.err);
        else if (got.kind === 'cool') markCool(ring, i, got.err, got.wait);
        else return { result: null, err: got.err };  // soft: not the key's fault, stop here
        idx = (i + 1) % n;
      }
      return { result: null, err: 'all ' + n + ' key(s) unavailable. last: ' + last };
    }

    return { fingerprint, mask, newRing, pick, usable, counts, importKeys, markDead, markNoCredit, markCool, markOk, reviveAll, reviveOne, deleteOne, rotate };
  })();

  // ---- one shared classifier for every provider, the table from quota-and-fallback.md §3 ----
  function krClassify(status, bodyText, headers) {
    const lower = (bodyText || '').toLowerCase();
    if (status === 403 && lower.includes('1010')) return { kind: 'soft', err: 'blocked by cloudflare (1010), not a key problem' };
    let wait = null;
    const ra = headers && headers.get ? headers.get('retry-after') : null;
    if (ra) { const n = parseFloat(ra); if (isFinite(n)) wait = n; }
    if (wait == null && headers && headers.get) {
      for (const h of ['x-ratelimit-reset-requests', 'x-ratelimit-reset-tokens', 'x-ratelimit-reset']) {
        const v = headers.get(h);
        if (v) { const n = parseFloat(v); if (isFinite(n)) { wait = n; break; } }
      }
    }
    const hasRetryHint = wait != null || /retrydelay|retry-after|try again in/.test(lower);
    const creditWords = /zero_credits|e0300|credit balance|insufficient|quota exceeded|out of credits|payment required|billing|depleted|prepayment/;
    // 401/403 is REJECTED: the key itself is bad, revoked, or invalid.
    // credit words under 400/429 is NO CREDIT: the key is real and the account
    // is alive, it simply cannot afford the work right now — a different fact
    // with a different fix (top up), so it gets its own state rather than
    // being buried alongside a genuinely dead key. See modules/keyring.md §2d.
    if (status === 401 || status === 403) return { kind: 'dead', err: 'HTTP ' + status + (bodyText ? ': ' + bodyText.slice(0, 160) : '') };
    if (status === 429) {
      if (!hasRetryHint && creditWords.test(lower)) return { kind: 'nocredit', err: 'out of credit' };
      return { kind: 'cool', err: 'rate limited', wait: wait != null ? Math.min(3600, Math.max(1, wait)) : 60 };
    }
    if (status === 400) {
      if (creditWords.test(lower)) return { kind: 'nocredit', err: 'out of credit' };
      return { kind: 'soft', err: 'bad request: ' + (bodyText || '').slice(0, 160) };
    }
    if (status === 404) return { kind: 'soft', err: 'wrong endpoint (404)' };
    if (status >= 500) return { kind: 'soft', err: 'provider error ' + status };
    return { kind: 'soft', err: 'HTTP ' + status };
  }

  // ---- per-provider rings, loaded from and saved to this browser only ----
  const KR_PROVIDERS = {
    claude:   { label: 'claude',                storageKey: 'maha_ring_claude',  prefixes: ['sk-ant-'] },
    gemini:   { label: 'gemini',                 storageKey: 'maha_ring_gemini',  prefixes: ['aq.'] },
    groq:     { label: 'groq (archive titles)',  storageKey: 'maha_ring_groq',    prefixes: ['gsk_'] },
    assembly: { label: 'assemblyai',             storageKey: 'maha_ring_assembly', prefixes: [] }
  };
  function loadRing(provider) {
    try {
      const raw = localStorage.getItem(KR_PROVIDERS[provider].storageKey);
      const parsed = raw ? JSON.parse(raw) : null;
      return (parsed && Array.isArray(parsed.keys)) ? parsed : KR.newRing();
    } catch (e) { return KR.newRing(); }
  }
  function saveRing(provider, ring) { localStorage.setItem(KR_PROVIDERS[provider].storageKey, JSON.stringify(ring)); }
  function ringHasKeys(provider) { return loadRing(provider).keys.length > 0; }

  const GROQ_CHAT_URL = 'https://api.groq.com/openai/v1/chat/completions';
  const SUMMARY_MODEL = 'llama-3.3-70b-versatile';
  const RESHAPE_PROMPT = 'Rewrite the text below so it flows well. Remove every repetition and merge everything into one clear, in a nutshell text that explains the whole message. You may rearrange sentences freely. Write exactly as a human would, with no sign that an AI wrote it. Do not use dashes, bullet points, headings, or any special formatting, only plain sentences with normal punctuation. Keep the length balanced, not too short and not too long, and the tone friendly but clear, never dry. Keep the original language of the text. Reply with the rewritten text only, nothing else.\n\nText:\n';
  const GRAMMAR_PROMPT = 'Correct only the grammar, spelling and punctuation of the text below. Do not rephrase, do not rearrange or merge sentences, do not change the wording, structure or shape of the text in any way. Make only the smallest necessary fixes to punctuation, capitalization, spelling and clear grammar mistakes, and leave everything else exactly as written. Keep the original language. Reply with the corrected text only, nothing else.\n\nText:\n';

  // ---- AssemblyAI, endpoints and models learned from the assembly ai v3 app ----
  const AAI_BASE = 'https://api.assemblyai.com';
  // bumped by the cancel button, any transcription started before the bump gives up
  let txCancelGen = 0;
  function txCanceled(gen) { return gen !== txCancelGen; }
  function txAbortError() { const e = new Error('canceled'); e.__canceled = true; return e; }
  const AAI_MODELS = ['universal-3-pro', 'universal-2'];

  function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
  function getAaiModel() { const m = localStorage.getItem('whisper_aai_model'); return AAI_MODELS.includes(m) ? m : AAI_MODELS[0]; }
  function getQModel() { return localStorage.getItem('whisper_qmodel') || 'gemini-2.5-flash'; }
  // The ring belongs to the server now, so readiness is a question for it.
  // Optimistic until told otherwise: a page that greys itself out while one
  // fetch is in flight is a page that jumps.
  let __ringHasKeys = true;
  fetch('/api/health', { headers: { 'X-Gtt-Local': '1' } })
    .then(r => r.json())
    .then(h => {
      __ringHasKeys = h.keys > 0;
      if (!h.keys) setStatus('no keys yet, open the KEYS tab and pick your key file', 'err');
    })
    .catch(() => {});
  function serviceReady() { return __ringHasKeys; }

  // ---- local usage statistic, persisted ----
  function getUsage() { try { return JSON.parse(localStorage.getItem('whisper_usage')) || { tx: 0, corr: 0 }; } catch (e) { return { tx: 0, corr: 0 }; } }
  function bumpUsage(kind) { const u = getUsage(); if (kind === 'tx') u.tx++; if (kind === 'corr') u.corr++; localStorage.setItem('whisper_usage', JSON.stringify(u)); updateBottomBar(); }

  // ---- persistent tiny cyan status line, model for transcription, model for correction, usage, credits ----
  function updateBottomBar() {
    const bar = document.getElementById('bottomBar');
    if (!bar) return;
    const txModel = 'assembly/' + getAaiModel();
    const corrModel = 'gemini/' + getQModel();
    const u = getUsage();
    const credits = getRemainingCredits(); // null when not applicable
    let s = 'tx ' + txModel + '   \u00B7   corr ' + corrModel + '   \u00B7   used ' + u.tx + ' tx / ' + u.corr + ' corr';
    if (lastProcSec > 0) s += '   \u00B7   last ' + lastProcSec.toFixed(1) + 's';
    if (credits !== null && credits !== undefined) s += '   \u00B7   credits ' + credits;
    bar.textContent = s;
  }
  // No public balance endpoint is used, so remaining credits stay not applicable.
  function getRemainingCredits() { return null; }

  // ---- upload with live progress, so we can show speed and eta of arrival ----
  let lastProcSec = 0; // processing score of the most recent transcription, in seconds
  function xhrUpload(url, headers, body, onProgress) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('POST', url);
      for (const h in headers) { try { xhr.setRequestHeader(h, headers[h]); } catch (e) {} }
      const t0 = performance.now();
      if (xhr.upload) {
        xhr.upload.onprogress = (e) => {
          if (!e.lengthComputable || !onProgress) return;
          const secs = (performance.now() - t0) / 1000;
          const speed = secs > 0 ? e.loaded / secs : 0; // bytes per second
          const eta = speed > 0 ? (e.total - e.loaded) / speed : 0; // seconds
          onProgress({ loaded: e.loaded, total: e.total, speed, eta, pct: e.total ? e.loaded / e.total : 0 });
        };
      }
      xhr.onload = () => resolve({ ok: xhr.status >= 200 && xhr.status < 300, status: xhr.status, responseText: xhr.responseText });
      xhr.onerror = () => reject(new Error('network error'));
      xhr.ontimeout = () => reject(new Error('timeout'));
      xhr.send(body);
    });
  }
  function fmtSpeed(bytesPerSec) {
    if (bytesPerSec >= 1048576) return (bytesPerSec / 1048576).toFixed(2) + ' MB/s';
    return (bytesPerSec / 1024).toFixed(0) + ' KB/s';
  }
  function fmtEta(secs) {
    secs = Math.max(0, Math.round(secs));
    const m = Math.floor(secs / 60), s = String(secs % 60).padStart(2, '0');
    return m + ':' + s;
  }
  function uploadMsg(prefix, p) {
    const pct = Math.round(p.pct * 100);
    return prefix + ' ' + pct + '%  \u00B7  ' + fmtSpeed(p.speed) + '  \u00B7  eta ' + fmtEta(p.eta);
  }

  function maskKey(k) { return k.length <= 12 ? k.slice(0, 4) + '...' : k.slice(0, 8) + '...' + k.slice(-4); }

  const meter = document.getElementById('meter');
  for (let i = 0; i < 24; i++) meter.appendChild(document.createElement('i'));
  function setMeter(state) { meter.className = 'meter ' + state; }

  // ---- tabs ----
  const sharedSettings = document.getElementById('sharedSettings');
  function updateSharedSettings(tab) {
    const show = (tab === 'rec' || tab === 'transcribe');
    sharedSettings.style.display = show ? '' : 'none';
    // recording is always AssemblyAI, so the service choice only belongs on the transcribe tab
  }
  const tabBtns = Array.from(document.querySelectorAll('.tab-btn'));
  const gearBtn = document.getElementById('gearBtn');
  const settingsPanel = document.getElementById('settingsPanel');
  let lastActiveTabBtn = tabBtns[0];

  // switches the whole screen to one tab, exactly like clicking its button would
  function activateTab(tabName) {
    const btn = tabBtns.find(b => b.dataset.tab === tabName);
    if (!btn) return;
    tabBtns.forEach(b => b.classList.toggle('active', b === btn));
    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
    document.getElementById('tab-' + tabName).classList.add('active');
    updateSharedSettings(tabName);
    gearBtn.classList.remove('active');
    lastActiveTabBtn = btn;
    if (tabName === 'arh') renderArchive();
  }
  tabBtns.forEach(btn => btn.addEventListener('click', () => {
    // the REC pill is the record button, from any tab, and never a refresh
    if (btn.dataset.tab === 'rec') {
      if (recPhase === 'recording') { stopAndTranscribe(); }
      else { activateTab('rec'); startRecording(); }
      return;
    }
    // hidden refresh: tapping the already-active tab reloads the whole page
    if (btn.classList.contains('active')) { location.reload(); return; }
    activateTab(btn.dataset.tab);
  }));

  // ---- settings, its own full tab, never inserted into whatever tab was open ----
