  renderAaiModels();

  // ---- API key ring panels: masked list, active radio, test/test-all,
  // delete, revive, import. States and glyphs follow Key_Tester's model
  // (github.com/markoboskoauroville/Key_Tester, HANDOFF.md "five states"):
  // untested, live/works, no credit, rejected, resting/throttled, and a
  // transient "unclear" for a soft result that never changes the ring.
  const KR_GLYPH = { untested: '\u25CB', testing: '\u2026', live: '\u25CF', nocredit: '$', dead: '\u2715', cool: '\u25D0', unclear: '?' };
  const KR_WORD = { untested: 'untested', testing: 'testing', live: 'live', nocredit: 'no credit', dead: 'rejected', cool: 'resting', unclear: 'unclear' };
  function krStateLabel(k) {
    if (k.state === 'dead') return 'dead';
    if (k.state === 'nocredit') return 'nocredit';
    if (k.state === 'cool' && (k.coolUntil || 0) > Date.now() / 1000) return 'cool';
    return k.calls > 0 ? 'live' : 'new';
  }
  const KR_BADGE_WORD = { dead: KR_WORD.dead, nocredit: KR_WORD.nocredit, cool: KR_WORD.cool, live: KR_WORD.live, new: KR_WORD.untested };
  const KR_BADGE_GLYPH = { dead: KR_GLYPH.dead, nocredit: KR_GLYPH.nocredit, cool: KR_GLYPH.cool, live: KR_GLYPH.live, new: KR_GLYPH.untested };
  function krRowMeta(k, label) {
    const bits = [];
    if (label === 'cool') { const secs = Math.max(0, Math.round((k.coolUntil || 0) - Date.now() / 1000)); bits.push('resting ' + secs + 's'); }
    if (k.lastError) bits.push('<span class="kr-verbatim">' + krEsc(k.lastError.slice(0, 90)) + '</span>');
    if (k.calls) bits.push(k.calls + ' call' + (k.calls === 1 ? '' : 's'));
    return bits.join('  \u00B7  ');
  }
  function krEsc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
  async function krProbe(provider, key) {
    // the smallest real, billable thing each provider sells, per keyring.md §2h.
    // never a plain list call: a spent account can still return 200 from a list
    // (Key_Tester HANDOFF.md's "two questions" — valid, and separately, funded).
    if (provider === 'claude') {
      const r = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-api-key': key, 'anthropic-version': '2023-06-01', 'anthropic-dangerous-direct-browser-access': 'true' },
        body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 1, messages: [{ role: 'user', content: 'hi' }] })
      });
      return r;
    }
    if (provider === 'gemini') {
      return fetch('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent', {
        method: 'POST', headers: { 'Content-Type': 'application/json', 'x-goog-api-key': key },
        body: JSON.stringify({ contents: [{ parts: [{ text: 'hi' }] }], generationConfig: { maxOutputTokens: 1 } })
      });
    }
    if (provider === 'groq') {
      return fetch(GROQ_CHAT_URL, {
        method: 'POST', headers: { 'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: SUMMARY_MODEL, messages: [{ role: 'user', content: 'hi' }], max_tokens: 1 })
      });
    }
    if (provider === 'assembly') {
      // a real one-second 440hz tone, per keyring.md §2i, generated on the spot rather than shipped as a file
      const wav = makeProbeWav();
      const up = await fetch(AAI_BASE + '/v2/upload', { method: 'POST', headers: { 'authorization': key }, body: wav });
      if (!up.ok) return up;
      const { upload_url } = await up.json();
      return fetch(AAI_BASE + '/v2/transcript', {
        method: 'POST', headers: { 'authorization': key, 'content-type': 'application/json' },
        body: JSON.stringify({ audio_url: upload_url, speech_model: getAaiModel() })
      });
    }
  }
  function makeProbeWav() {
    // 1s, 16kHz, mono, 16-bit PCM, 440Hz at quarter scale — the exact fixture keyring.md §2i specifies
    const n = 16000, buf = new ArrayBuffer(44 + n * 2), dv = new DataView(buf);
    const wStr = (o, s) => { for (let i = 0; i < s.length; i++) dv.setUint8(o + i, s.charCodeAt(i)); };
    wStr(0, 'RIFF'); dv.setUint32(4, 36 + n * 2, true); wStr(8, 'WAVE'); wStr(12, 'fmt ');
    dv.setUint32(16, 16, true); dv.setUint16(20, 1, true); dv.setUint16(22, 1, true);
    dv.setUint32(24, 16000, true); dv.setUint32(28, 32000, true); dv.setUint16(32, 2, true); dv.setUint16(34, 16, true);
    wStr(36, 'data'); dv.setUint32(40, n * 2, true);
    for (let i = 0; i < n; i++) dv.setInt16(44 + i * 2, Math.trunc(8000 * Math.sin(2 * Math.PI * 440 * i / 16000)), true);
    return new Blob([buf], { type: 'audio/wav' });
  }
  function krLiveLine(provider, html) {
    const el = document.getElementById('kr-live-' + provider);
    if (el) el.innerHTML = html || '';
  }
  // one key, one probe. Returns the badge state actually reached, so a bulk
  // "test all" can report a running tally the way Key_Tester's live line does.
  async function krTestOne(provider, idx) {
    const ring = loadRing(provider);
    const key = ring.keys[idx]; if (!key) return null;
    const masked = KR.mask(key.key);
    krLiveLine(provider, '<span class="kr-glyph testing">' + KR_GLYPH.testing + '</span> testing \u00b7 ' + krEsc(masked));
    let reached = 'unclear';
    try {
      const res = await krProbe(provider, key.key);
      if (res.ok) {
        KR.markOk(ring, idx); reached = 'live';
      } else {
        const bodyText = await res.text().catch(() => '');
        const v = krClassify(res.status, bodyText, res.headers);
        if (v.kind === 'dead') { KR.markDead(ring, idx, v.err); reached = 'dead'; }
        else if (v.kind === 'nocredit') { KR.markNoCredit(ring, idx, v.err); reached = 'nocredit'; }
        else if (v.kind === 'cool') { KR.markCool(ring, idx, v.err, v.wait); reached = 'cool'; }
        else { key.lastError = v.err; reached = 'unclear'; }   // soft: never changes the ring, per Key_Tester's own rule
      }
    } catch (e) { key.lastError = 'no connection: ' + e.message; reached = 'unclear'; }
    saveRing(provider, ring);
    const glyph = KR_GLYPH[reached] || KR_GLYPH.unclear;
    const word = KR_WORD[reached] || KR_WORD.unclear;
    krLiveLine(provider, '<span class="kr-glyph ' + reached + '">' + glyph + '</span> ' + krEsc(masked) + ' \u00b7 ' + word);
    return reached;
  }
  async function krTestKey(provider, idx) {
    renderKeyringPanels();
    await krTestOne(provider, idx);
    renderKeyringPanels();
  }
  async function krTestAll(provider) {
    const ring = loadRing(provider);
    const n = ring.keys.length;
    if (!n) return;
    const btn = document.querySelector('[data-act=test-all][data-provider=' + provider + ']');
    if (btn) btn.disabled = true;
    for (let i = 0; i < n; i++) {
      await krTestOne(provider, i);
      krLiveLine(provider, (document.getElementById('kr-live-' + provider) || {}).innerHTML + '  \u00b7  ' + (i + 1) + '/' + n);
    }
    krLiveLine(provider, '\u2713 done \u00b7 ' + n + '/' + n);
    if (btn) btn.disabled = false;
    renderKeyringPanels();
  }
  function krImport(provider, raw) {
    const cfg = KR_PROVIDERS[provider];
    const ring = loadRing(provider);
    KR.importKeys(ring, raw, cfg.prefixes).then(added => {
      saveRing(provider, ring);
      renderKeyringPanels(added > 0 ? ('imported ' + added + ' new ' + cfg.label + ' key(s)') : ('no new ' + cfg.label + ' keys found in that text'));
    });
  }
  function renderKeyringPanels(flash) {
    const wrap = document.getElementById('keyringPanels'); if (!wrap) return;
    wrap.innerHTML = Object.keys(KR_PROVIDERS).map(provider => {
      const cfg = KR_PROVIDERS[provider];
      const ring = loadRing(provider);
      const c = KR.counts(ring);
      const untested = ring.keys.filter(k => krStateLabel(k) === 'new').length;
      // the exact Key_Tester summary shape: "<file> · N keys · X work · C no credit · Y rejected · Z untested"
      const summary = c.total + ' key' + (c.total === 1 ? '' : 's') +
        '  \u00B7  ' + c.live + ' live' +
        '  \u00B7  ' + c.nocredit + ' no credit' +
        '  \u00B7  ' + c.dead + ' rejected' +
        '  \u00B7  ' + untested + ' untested';
      const rows = ring.keys.length === 0
        ? '<div class="kr-empty">no keys yet, import below</div>'
        : ring.keys.map((k, i) => {
            const label = krStateLabel(k);
            const meta = krRowMeta(k, label);
            const glyph = KR_BADGE_GLYPH[label], word = KR_BADGE_WORD[label];
            return '<div class="kr-row">' +
              '<input type="radio" name="kr-active-' + provider + '" ' + (i === (ring.active || 0) ? 'checked' : '') + ' data-provider="' + provider + '" data-idx="' + i + '" class="kr-active-radio">' +
              '<div class="kr-info"><div class="kr-mask">' + KR.mask(k.key) + '<span class="kr-badge ' + label + '"><span class="kr-glyph">' + glyph + '</span> ' + word + '</span></div>' +
              (meta ? '<div class="kr-meta">' + meta + '</div>' : '') + '</div>' +
              '<div class="kr-row-actions">' +
              '<button type="button" class="kr-mini-btn" data-act="test" data-provider="' + provider + '" data-idx="' + i + '">test</button>' +
              (label === 'dead' || label === 'nocredit' || label === 'cool' ? '<button type="button" class="kr-mini-btn" data-act="revive" data-provider="' + provider + '" data-idx="' + i + '">revive</button>' : '') +
              '<button type="button" class="kr-mini-btn danger" data-act="delete" data-provider="' + provider + '" data-idx="' + i + '">delete</button>' +
              '</div></div>';
          }).join('');
      return '<div class="kr-panel">' +
        '<div class="kr-head"><span class="kr-title">' + cfg.label + '</span>' +
        (ring.keys.length > 1 ? '<button type="button" class="kr-mini-btn" data-act="test-all" data-provider="' + provider + '">test all</button>' : '') +
        '</div>' +
        '<div class="kr-count">' + summary + '</div>' +
        '<div class="kr-live" id="kr-live-' + provider + '"></div>' +
        rows +
        '<div class="kr-import">' +
        '<textarea id="kr-paste-' + provider + '" placeholder="paste keys here, or browse a file below"></textarea>' +
        '<div class="kr-import-row">' +
        '<button type="button" class="small-btn" data-act="import-paste" data-provider="' + provider + '">import pasted text</button>' +
        '<label class="small-btn" style="text-align:center;cursor:pointer;">browse file<input type="file" accept=".txt,text/plain" data-provider="' + provider + '" class="kr-file-input" style="display:none;"></label>' +
        '</div></div></div>';
    }).join('') + (flash ? '<div class="status ok">' + flash + '</div>' : '');

    Array.from(wrap.querySelectorAll('.kr-active-radio')).forEach(r => r.addEventListener('change', () => {
      const ring = loadRing(r.dataset.provider); ring.active = parseInt(r.dataset.idx, 10); saveRing(r.dataset.provider, ring); renderKeyringPanels();
    }));
    Array.from(wrap.querySelectorAll('[data-act=test]')).forEach(b => b.addEventListener('click', () => krTestKey(b.dataset.provider, parseInt(b.dataset.idx, 10))));
    Array.from(wrap.querySelectorAll('[data-act=test-all]')).forEach(b => b.addEventListener('click', () => krTestAll(b.dataset.provider)));
    Array.from(wrap.querySelectorAll('[data-act=revive]')).forEach(b => b.addEventListener('click', () => {
      const ring = loadRing(b.dataset.provider); KR.reviveOne(ring, parseInt(b.dataset.idx, 10)); saveRing(b.dataset.provider, ring); renderKeyringPanels();
    }));
    Array.from(wrap.querySelectorAll('[data-act=delete]')).forEach(b => b.addEventListener('click', () => {
      const ring = loadRing(b.dataset.provider); KR.deleteOne(ring, parseInt(b.dataset.idx, 10)); saveRing(b.dataset.provider, ring); renderKeyringPanels();
    }));
    Array.from(wrap.querySelectorAll('[data-act=import-paste]')).forEach(b => b.addEventListener('click', () => {
      const ta = document.getElementById('kr-paste-' + b.dataset.provider);
      if (ta && ta.value.trim()) krImport(b.dataset.provider, ta.value);
    }));
    Array.from(wrap.querySelectorAll('.kr-file-input')).forEach(inp => inp.addEventListener('change', () => {
      const f = inp.files[0]; if (!f) return;
      const reader = new FileReader();
      reader.onload = () => krImport(inp.dataset.provider, String(reader.result || ''));
      reader.readAsText(f);
    }));
  }
  renderKeyringPanels();

  // ---- correction model selector (settings), the Q tab no longer carries it ----
  const CORR_MODELS = [
    { id: 'gemini-2.5-pro', label: 'PRO' },
    { id: 'gemini-2.5-flash', label: 'FLASH' },
    { id: 'gemini-2.5-flash-lite', label: 'LITE' }
  ];
  const corrModelList = document.getElementById('corrModelList');
  function renderCorrModels() {
    // likewise: the model is chosen by the server now, so there is no list
    if (!corrModelList) return;
    const cur = getQModel();
    corrModelList.innerHTML = CORR_MODELS.map(m =>
      '<button type="button" class="lang-btn corr-model' + (m.id === cur ? ' active' : '') + '" data-model="' + m.id + '">' + m.label + '</button>'
    ).join('');
    Array.from(corrModelList.querySelectorAll('.corr-model')).forEach(b => b.addEventListener('click', () => {
      localStorage.setItem('whisper_qmodel', b.dataset.model);
      renderCorrModels();
      updateBottomBar();
    }));
  }
  renderCorrModels();

  updateBottomBar();

  // ---- transcribe tab ----
  const drop = document.getElementById('drop');
  const dropLabel = document.getElementById('dropLabel');
  const audioInput = document.getElementById('audioInput');
  const langButtons = Array.from(document.querySelectorAll('.lang-btn')).filter(b => b.dataset.lang && !b.classList.contains('tl-from') && !b.classList.contains('tl-to'));
  const transcribeBtn = document.getElementById('transcribeBtn');
  const statusEl = document.getElementById('status');
  const transcriptEl = document.getElementById('transcript');
  const copyBtn = document.getElementById('copyBtn');

  let selectedLang = localStorage.getItem('whisper_lang') || 'auto';
  let forcedLang = null; // set by archive retranscribe to override the transcribe-tab language
  function activeLang() { return forcedLang || selectedLang; }

  function applyLangUI() {
    langButtons.forEach(b => {
      const active = b.dataset.lang === selectedLang;
      b.classList.toggle('active', active);
      b.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
  }
  applyLangUI();
  langButtons.forEach(btn => btn.addEventListener('click', () => {
    selectedLang = btn.dataset.lang;
    localStorage.setItem('whisper_lang', selectedLang);
    applyLangUI();
  }));

  // ---- ffmpeg optimization: convert whatever was picked into small mono
  // speech-ready Opus before it ever reaches the AssemblyAI ring. Runs the
  // moment a file is chosen, not on the TRANSCRIBE press, so there is
  // nothing to wait for once the button is actually pressed.
  let ffmpegAvailable = null; // null = not checked yet
  let pickedFile = null;      // the raw File the person chose
  let optimizedBlob = null;   // the ffmpeg result, or the raw file if ffmpeg is unavailable/failed
  let optimizing = false;

  async function checkFfmpeg() {
    if (ffmpegAvailable !== null) return ffmpegAvailable;
    try {
      const r = await fetch('/api/ffmpeg', { headers: { 'X-Maha-Local': '1' } });
      const d = await r.json();
      ffmpegAvailable = !!d.available;
    } catch (e) { ffmpegAvailable = false; }
    return ffmpegAvailable;
  }
  function fmtMBshort(n) { return (n / 1048576).toFixed(1) + ' MB'; }

  async function optimizePickedFile() {
    const file = pickedFile;
    if (!file) return;
    optimizing = true;
    optimizedBlob = file; // safe default: the raw file, used if ffmpeg is absent or fails
    updateTranscribeState();

    const hasFfmpeg = await checkFfmpeg();
    if (!hasFfmpeg) {
      setStatus('ffmpeg not found on the server, sending the file as-is', 'err');
      optimizing = false; updateTranscribeState();
      return;
    }

    setStatus('optimizing audio with ffmpeg\u2026');
    try {
      const fd = new FormData();
      fd.append('file', file, file.name);
      const r = await fetch('/api/optimize-audio', {
        method: 'POST', headers: { 'X-Maha-Local': '1' }, body: fd
      });
      if (!r.ok) {
        const d = await r.json().catch(() => ({}));
        setStatus('ffmpeg: ' + (d.error || ('HTTP ' + r.status)) + '  \u00B7  sending the original file instead', 'err');
        optimizing = false; updateTranscribeState();
        return;
      }
      const blob = await r.blob();
      const before = parseInt(r.headers.get('X-Original-Bytes') || file.size, 10);
      const after = parseInt(r.headers.get('X-Optimized-Bytes') || blob.size, 10);
      optimizedBlob = new File([blob], (file.name || 'audio').replace(/\.[^.]+$/, '') + '.ogg', { type: 'audio/ogg' });
      const pct = before > 0 ? Math.round(100 * (1 - after / before)) : 0;
      setStatus('optimized  \u00B7  ' + fmtMBshort(before) + ' \u2192 ' + fmtMBshort(after) + (pct > 0 ? '  (\u2212' + pct + '%)' : ''), 'ok');
    } catch (e) {
      setStatus('ffmpeg request failed: ' + e.message + '  \u00B7  sending the original file instead', 'err');
    }
    optimizing = false; updateTranscribeState();
  }

  audioInput.addEventListener('change', () => {
    const f = audioInput.files[0];
    pickedFile = f || null;
    optimizedBlob = null;
    if (f) { dropLabel.textContent = f.name; drop.classList.add('has-file'); optimizePickedFile(); }
    else { dropLabel.textContent = 'CHOOSE FILE'; drop.classList.remove('has-file'); }
    updateTranscribeState();
  });

  function updateTranscribeState() {
    transcribeBtn.disabled = !(pickedFile && !optimizing && serviceReady());
  }
  updateTranscribeState();
  if (!ringHasKeys('assembly')) {
    openSettings();
  }

  function setStatus(text, kind) {
    statusEl.textContent = text;
    statusEl.className = 'status' + (kind ? ' ' + kind : '');
  }
  // the message now comes from the health check above, once it answers



  // ---- AssemblyAI, mirrors the v3 app, upload then transcript then poll ----
  function aaiSpeechModels() {
    const sel = getAaiModel();
    const arr = [sel];
    AAI_MODELS.forEach(m => { if (!arr.includes(m)) arr.push(m); });
    return arr; // chosen model first, the rest as fallback for AssemblyAI
  }
  function aaiLangConfig() {
    const speech_models = aaiSpeechModels();
    const lang = activeLang();
    if (lang === 'hr') return { language_code: 'hr', speech_models };
    if (lang === 'auto') return { language_detection: true, speech_models };
    return { language_code: 'en', speech_models };
  }
  async function aaiError(res) {
    try { const j = await res.json(); return j.error || j.message || ('HTTP ' + res.status); }
    catch (e) { return 'HTTP ' + res.status; }
  }
  // one key does the WHOLE job — upload, submit, poll — never rotating mid-job,
  // because an upload belongs to the account that made it (keyring.md §2b).
  // returns {kind, result, err, wait} rather than throwing, so the ring can classify it.
  async function aaiAttemptJob(key, blob, statusFn) {
    const gen = txCancelGen;
    const keyLabel = KR.mask(key);
    try {
      const up = await xhrUpload(AAI_BASE + '/v2/upload', { 'authorization': key, 'content-type': 'application/octet-stream' }, blob,
        (p) => statusFn('assembly ' + keyLabel + '  \u00B7  ' + uploadMsg('upload', p)));
      if (txCanceled(gen)) return { kind: 'canceled' };
      if (!up.ok) {
        let bodyText = up.responseText || '';
        return krClassify(up.status, bodyText, { get: () => null });
      }
      const upload_url = JSON.parse(up.responseText).upload_url;

      const tr = await fetch(AAI_BASE + '/v2/transcript', {
        method: 'POST',
        headers: { 'authorization': key, 'content-type': 'application/json' },
        body: JSON.stringify({ audio_url: upload_url, ...aaiLangConfig() })
      });
      if (txCanceled(gen)) return { kind: 'canceled' };
      if (!tr.ok) { const bodyText = await tr.text().catch(() => ''); return krClassify(tr.status, bodyText, tr.headers); }
      const { id } = await tr.json();

      const procStart = performance.now();
      // short parts finish fast, so check quickly at first and back off to 3s for long audio
      for (let i = 0; i < 260; i++) {
        await sleep(i < 4 ? 600 : (i < 10 ? 1200 : 3000));
        if (txCanceled(gen)) return { kind: 'canceled' };
        const poll = await fetch(AAI_BASE + '/v2/transcript/' + id, { headers: { 'authorization': key } });
        if (!poll.ok) { const bodyText = await poll.text().catch(() => ''); return krClassify(poll.status, bodyText, poll.headers); }
        const data = await poll.json();
        if (data.status === 'completed') return { kind: 'ok', result: (data.text || '').trim() };
        // a failed job answers HTTP 200 (keyring.md trap #3), so read the status inside the body,
        // and it is a soft failure: the job was bad, not the key
        if (data.status === 'error') return { kind: 'soft', err: data.error || 'transcription failed' };
        statusFn('assembly ' + keyLabel + '  \u00B7  processing ' + Math.round((performance.now() - procStart) / 1000) + 's');
      }
      return { kind: 'soft', err: 'timeout, audio may be too long' };
    } catch (e) { return { kind: 'soft', err: 'network error: ' + e.message }; }
  }
  async function aaiTranscribe(blob, filename, statusFn) {
    const ring = loadRing('assembly');
    if (!ring.keys.length) { statusFn('no assemblyai keys, add one in settings', 'err'); return null; }
    const { result, err, canceled } = await KR.rotate(ring, (key) => aaiAttemptJob(key, blob, statusFn));
    saveRing('assembly', ring);
    if (canceled) return null;
    if (result === null && err) statusFn('assembly: ' + err, 'err');
    return result;
  }

  // ---- GEMINI, through this app own server ----
  // The one seam. Upstream this called aaiTranscribe and the browser held the
  // keys. Here the blob goes to /api/listen and the server ring answers it, so
  // the keys stay on disk and the same fallback, ledger and daily budget cover
  // transcription too. Everything above and below this function is untouched.
  async function transcribeDispatch(blob, filename, statusFn) {
    const gen = txCancelGen;
    statusFn('gemini  \u00b7  sending ' + Math.round(blob.size / 1024) + ' KB');
    try {
      const fd = new FormData();
      fd.append('audio', blob, filename || 'audio.webm');
      const lang = activeLang();
      fd.append('lang', lang === 'hr' ? 'Croatian' : (lang === 'en' ? 'English' : ''));
      const r = await fetch('/api/listen', { method: 'POST',
        headers: { 'X-Gtt-Local': '1' }, body: fd });
      if (txCanceled(gen)) return null;
      const j = await r.json();
      if (!j.ok) { statusFn('gemini: ' + (j.error || 'failed'), 'err'); return null; }
      statusFn('gemini  \u00b7  ' + j.seconds + 's heard on [' + j.key + ']');
      return (j.text || '').trim();
    } catch (e) {
      statusFn('gemini: ' + e.message, 'err');
      return null;
    }
  }

  // titles and summaries for the archive, on groq because it is free
  async function groqSummarize(text) {
    const ring = loadRing('groq');
    if (!ring.keys.length) return null;
    const prompt = 'You will receive a transcript. Reply with strict JSON only, no markdown, in this exact shape: {"title": "...", "summary": "..."}. title is 3 to 6 words in the language of the transcript, suitable as a file name, no punctuation except spaces. summary is 1 to 3 sentences in the same language.\n\nTranscript:\n' + text.slice(0, 12000);
    const { result } = await KR.rotate(ring, async (key) => {
      try {
        const r = await fetch(GROQ_CHAT_URL, {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json' },
          body: JSON.stringify({ model: SUMMARY_MODEL, messages: [{ role: 'user', content: prompt }], temperature: 0.3, max_tokens: 300 })
        });
        if (r.ok) {
          const d = await r.json();
          let raw = ((d.choices && d.choices[0] && d.choices[0].message && d.choices[0].message.content) || '').trim();
          const a = raw.indexOf('{'), b = raw.lastIndexOf('}');
          if (a !== -1 && b !== -1) raw = raw.slice(a, b + 1);
          try { const j = JSON.parse(raw); return { kind: 'ok', result: { title: j.title || '', summary: j.summary || '' } }; }
          catch (e) { return { kind: 'soft', err: 'unparsable reply' }; }
        }
        const bodyText = await r.text().catch(() => '');
        return krClassify(r.status, bodyText, r.headers);
      } catch (e) { return { kind: 'soft', err: 'network error: ' + e.message }; }
    });
    saveRing('groq', ring);
    return result;
  }



  // ---- generic Gemini text call with key fallback, used by grammar and translate ----
  async function geminiGenerate(prompt, model, statusFn) {
    const ring = loadRing('gemini');
    if (!ring.keys.length) { if (statusFn) statusFn('no gemini keys, add one in settings', 'err'); return null; }
    const payload = { contents: [{ parts: [{ text: prompt }] }] };
    const { result, err } = await KR.rotate(ring, async (key) => {
      try {
        const r = await fetch('https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'x-goog-api-key': key },
          body: JSON.stringify(payload)
        });
        if (r.ok) {
          const data = await r.json();
          const parts = (data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts) || [];
          return { kind: 'ok', result: { text: parts.map(p => p.text || '').join('').trim(), key } };
        }
        const bodyText = await r.text().catch(() => '');
        return krClassify(r.status, bodyText, r.headers);
      } catch (e) { return { kind: 'soft', err: 'network error: ' + e.message }; }
    });
    saveRing('gemini', ring);
    if (!result && statusFn) statusFn('gemini: ' + (err || 'failed'), 'err');
    return result;
  }

  // transcribe a queue of segments one by one, then stitch the transcripts
  async function transcribeSegmentsSeq(segments, statusFn) {
    const parts = [];
    for (let i = 0; i < segments.length; i++) {
      const label = segments.length > 1 ? ('segment ' + (i + 1) + '/' + segments.length + '  \u00B7  ') : '';
      const t = await transcribeDispatch(segments[i], 'segment_' + (i + 1) + '.webm', (m) => statusFn(label + m));
      if (t === null) return null; // one segment failed, fail the whole session
      parts.push((t || '').trim());
    }
    return parts.filter(Boolean).join('\n\n');
  }

  function runTranscriptionSession(segments, statusFn, onDone) {
    if (!segments || segments.length === 0) { statusFn('nothing to transcribe', 'err'); onDone(null); return; }
    const gen = txCancelGen;
    setMeter('busy');
    const t0 = performance.now();
    transcribeSegmentsSeq(segments, statusFn).then(text => {
      if (text !== null) {
        lastProcSec = (performance.now() - t0) / 1000;
        setMeter('ok');
        const segTxt = segments.length > 1 ? segments.length + ' segments  \u00B7  ' : '';
        statusFn('done  \u00B7  ' + segTxt + 'score ' + lastProcSec.toFixed(1) + 's', 'ok');
        bumpUsage('tx');
        updateBottomBar();
      } else if (txCanceled(gen)) {
        setMeter('idle');            // the user canceled, that is not an error
      } else {
        setMeter('err');
      }
      setTimeout(() => setMeter('idle'), 1600);
      onDone(text);
    });
  }

  transcribeBtn.addEventListener('click', () => {
    const file = optimizedBlob || pickedFile;
    if (!file) return;
    transcribeBtn.disabled = true;
    runTranscriptionSession([file], setStatus, (text) => {
      if (text !== null) transcriptEl.value = text;
      updateTranscribeState();
    });
  });

  copyBtn.addEventListener('click', () => {
    const text = transcriptEl.value;
    if (!text) return;
    const done = () => {
      const old = copyBtn.textContent;
      copyBtn.textContent = 'copied';
      setTimeout(() => { copyBtn.textContent = old; }, 1400);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text, done));
    } else fallbackCopy(text, done);
  });
  function fallbackCopy(text, done) {
    const ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); done(); } catch (e) {}
    document.body.removeChild(ta);
  }

  // ---- IndexedDB archive ----
  let db = null;
  function openDB() {
    return new Promise((resolve, reject) => {
      if (db) return resolve(db);
      const req = indexedDB.open('whisper_arh', 3);
      req.onupgradeneeded = (ev) => {
        const d = req.result;
        if (!d.objectStoreNames.contains('recordings')) d.createObjectStore('recordings', { keyPath: 'id', autoIncrement: true });
        // 'live' holds timeslice chunks of the segment being recorded, for mid-segment crash recovery
        if (!d.objectStoreNames.contains('live')) d.createObjectStore('live', { keyPath: 'id', autoIncrement: true });
        // 'segments' holds each finalized segment file, written and closed on every pause
        if (!d.objectStoreNames.contains('segments')) d.createObjectStore('segments', { keyPath: 'id', autoIncrement: true });
      };
      req.onsuccess = () => { db = req.result; resolve(db); };
      req.onerror = () => reject(req.error);
    });
  }
  function dbAdd(rec) { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('recordings', 'readwrite').objectStore('recordings').add(rec); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); })); }
  function dbAll() { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('recordings').objectStore('recordings').getAll(); r.onsuccess = () => res(r.result || []); r.onerror = () => rej(r.error); })); }
  function dbDelete(id) { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('recordings', 'readwrite').objectStore('recordings').delete(id); r.onsuccess = () => res(); r.onerror = () => rej(r.error); })); }
  function dbGet(id) { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('recordings').objectStore('recordings').get(id); r.onsuccess = () => res(r.result || null); r.onerror = () => rej(r.error); })); }
  function dbUpdate(rec) { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('recordings', 'readwrite').objectStore('recordings').put(rec); r.onsuccess = () => res(); r.onerror = () => rej(r.error); })); }

  // ---- live chunk store, written to on every timeslice so nothing is lost on a kill ----
  function liveAdd(rec) { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('live', 'readwrite').objectStore('live').add(rec); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); })); }
  function liveAll() { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('live').objectStore('live').getAll(); r.onsuccess = () => res(r.result || []); r.onerror = () => rej(r.error); })); }
  function liveClear() { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('live', 'readwrite').objectStore('live').clear(); r.onsuccess = () => res(); r.onerror = () => rej(r.error); })); }

  // ---- finalized segment store, one closed file per pause ----
  function segAdd(rec) { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('segments', 'readwrite').objectStore('segments').add(rec); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); })); }
  function segAll() { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('segments').objectStore('segments').getAll(); r.onsuccess = () => res(r.result || []); r.onerror = () => rej(r.error); })); }
  function segClear() { return openDB().then(d => new Promise((res, rej) => { const r = d.transaction('segments', 'readwrite').objectStore('segments').clear(); r.onsuccess = () => res(); r.onerror = () => rej(r.error); })); }

  // ---- recorder ----
  const RECORD_GLYPH = 'REC';   // three letter label
  const TRANSCRIBE_GLYPH = 'TRA'; // shown while recording, pressing it stops and transcribes

  // ---- live waveform, drawn straight from the mic while a part is recording ----
  let scopeCtx = null, scopeAnalyser = null, scopeRAF = null, scopeSource = null, scopeData = null;
  function drawScopeIdle() {
    if (!recScope || !recScope.getContext) return;
    const c = recScope.getContext('2d'); if (!c) return;
    const w = recScope.width, h = recScope.height;
    c.clearRect(0, 0, w, h);
    c.strokeStyle = 'rgba(139, 148, 158, 0.35)'; c.lineWidth = 2;
    c.beginPath(); c.moveTo(0, h / 2); c.lineTo(w, h / 2); c.stroke();
  }
  function startScope(stream) {
    stopScope();
    if (!recScope || !recScope.getContext) return;
    try {
      const AC = window.AudioContext || window.webkitAudioContext; if (!AC) return;
      scopeCtx = new AC();
      scopeAnalyser = scopeCtx.createAnalyser();
      scopeAnalyser.fftSize = 2048;
      scopeData = new Uint8Array(scopeAnalyser.fftSize);
      scopeSource = scopeCtx.createMediaStreamSource(stream);
      scopeSource.connect(scopeAnalyser);   // analyser only, nothing goes to the speakers
    } catch (e) { scopeAnalyser = null; return; }
    const c = recScope.getContext('2d'); if (!c) return;
    const draw = () => {
      if (!scopeAnalyser) return;
      scopeRAF = requestAnimationFrame(draw);
      scopeAnalyser.getByteTimeDomainData(scopeData);
      const w = recScope.width, h = recScope.height;
      c.clearRect(0, 0, w, h);
      c.lineWidth = 2; c.strokeStyle = '#e85d5d';
      c.beginPath();
      const step = w / scopeData.length;
      for (let i = 0; i < scopeData.length; i++) {
        const y = (scopeData[i] / 128.0) * (h / 2);
        const x = i * step;
        if (i === 0) c.moveTo(x, y); else c.lineTo(x, y);
      }
      c.stroke();
    };
    draw();
  }
  function stopScope() {
    if (scopeRAF) { cancelAnimationFrame(scopeRAF); scopeRAF = null; }
    if (scopeSource) { try { scopeSource.disconnect(); } catch (e) {} scopeSource = null; }
    scopeAnalyser = null; scopeData = null;
    if (scopeCtx) { try { scopeCtx.close(); } catch (e) {} scopeCtx = null; }
    drawScopeIdle();
  }
  const recClock = document.getElementById('recClock');
  const recState = document.getElementById('recState');
  const recCancelBtn = document.getElementById('recCancelBtn');
  const recPill = document.getElementById('recPill');
  const recPillLabel = document.getElementById('recPillLabel');
  const recScope = document.getElementById('recScope');
  const recStatus = document.getElementById('recStatus');
  const recTranscribeBtn = document.getElementById('recTranscribeBtn');

  let mediaRecorder = null, currentChunks = [], recTimer = null, elapsedMs = 0, lastTick = 0;
  let recPhase = 'idle'; // idle | recording
  let finalDurationMs = 0;
  let recStream = null, takeId = 0, segIndex = 0, seqInSeg = 0, recMime = 'audio/webm';
  let wakeLock = null, keepAudioCtx = null;
  let pendingFinalize = null; // 'stop', what to do once the current segment closes
  let takeSegments = [];      // finalized files for the take that is running right now
  let stitching = false;

  // ---- SESSION ----
  // a session is one archive entry that grows: every stop adds its audio and appends its transcript
  let sessionRecId = null;      // archive record id, null until the first stop of the session
  let sessionSegs = [];         // every audio part recorded in this session
  let sessionTranscript = '';   // the appended transcript of the whole session
  let sessionDurationMs = 0;    // total recorded time in this session
  let sessionName = '';
  let sessionParts = [];        // one slot per recorded part, filled in when its transcript lands
  let sessionPending = 0;       // how many parts are transcribing right now
  let sessionBusy = false;      // true while any transcription is running
  let sessionGen = 0;           // bumped on every reset, so a late transcript cannot land in a new session

  // ---- MODE ----
  // multi  : every recording is added under the last one, all parts in one archive entry
  // single : every recording replaces the text and starts its own archive entry
  function getRecMode() { return localStorage.getItem('maha_rec_mode') === 'single' ? 'single' : 'multi'; }

  const TIMESLICE_MS = 3000; // flush a chunk to disk every few seconds so a kill loses at most this much
  const TAKE_META_KEY = 'maha_take_meta';

  function setRecStatus(text, kind) { recStatus.textContent = text; recStatus.className = 'status' + (kind ? ' ' + kind : ''); }

  // clock shows one tenth of a second
  function fmtClock(ms) {
    const m = Math.floor(ms / 60000), s2 = Math.floor((ms % 60000) / 1000), tenth = Math.floor((ms % 1000) / 100);
    return String(m).padStart(2, '0') + ':' + String(s2).padStart(2, '0') + '<span class="ms">.' + tenth + '</span>';
  }
  function fmtDuration(ms) {
    const total = Math.round(ms / 1000);
    const m = Math.floor(total / 60), s = String(total % 60).padStart(2, '0');
    return m + ':' + s;
  }
  function fmtMB(bytes) { return (bytes / 1048576).toFixed(2) + ' MB'; }

  function tick() { const now = performance.now(); elapsedMs += now - lastTick; lastTick = now; recClock.innerHTML = fmtClock(elapsedMs); updatePillClock(); }
  function startClock() { lastTick = performance.now(); recTimer = setInterval(tick, 50); }
  function stopClock() { clearInterval(recTimer); recTimer = null; }

  // ---- keep the tab alive in the background ----
  async function requestWakeLock() {
    try { if ('wakeLock' in navigator) { wakeLock = await navigator.wakeLock.request('screen'); } } catch (e) {}
  }
  function releaseWakeLock() {
    try { if (wakeLock) { wakeLock.release(); wakeLock = null; } } catch (e) {}
  }
  // a truly silent audio node, active audio makes some Android browsers keep the page running
  function startKeepAlive() {
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      keepAudioCtx = new Ctx();
      const osc = keepAudioCtx.createOscillator();
      const gain = keepAudioCtx.createGain();
      gain.gain.value = 0; // silent
      osc.connect(gain); gain.connect(keepAudioCtx.destination);
      osc.start();
      keepAudioCtx._osc = osc;
    } catch (e) {}
  }
  function stopKeepAlive() {
    try { if (keepAudioCtx) { if (keepAudioCtx._osc) keepAudioCtx._osc.stop(); keepAudioCtx.close(); keepAudioCtx = null; } } catch (e) {}
  }

  function writeTakeMeta() {
    try { localStorage.setItem(TAKE_META_KEY, JSON.stringify({ take: takeId, mime: recMime, startedAt: Date.now(), elapsedMs: Math.round(elapsedMs), segIndex })); } catch (e) {}
  }
  function clearTakeMeta() { try { localStorage.removeItem(TAKE_META_KEY); } catch (e) {} }

  // the REC pill is the record button, it shows the running time while recording
  function setToggleUI() {
    if (!recPill) { updateCancelState(); return; }
    if (recPhase === 'recording') {
      recPill.classList.add('recording');
      recPill.title = 'stop and transcribe';
      recPill.setAttribute('aria-label', 'stop and transcribe');
      updatePillClock();
    } else {
      recPill.classList.remove('recording');
      recPill.title = 'record';
      recPill.setAttribute('aria-label', 'record');
      if (recPillLabel) recPillLabel.textContent = RECORD_GLYPH;
    }
    updateCancelState();
  }
  // mm:ss inside the pill, no tenths, the pill is small
  function updatePillClock() {
    if (!recPillLabel || recPhase !== 'recording') return;
    const total = Math.floor(elapsedMs / 1000);
    const mm = String(Math.floor(total / 60)).padStart(2, '0');
    const ss = String(total % 60).padStart(2, '0');
    recPillLabel.textContent = mm + ':' + ss;
  }
  function updateCancelState() {
    if (recCancelBtn) recCancelBtn.disabled = !(recPhase === 'recording' || sessionPending > 0);
  }
  function updateRecTranscribeState() { recTranscribeBtn.disabled = !(sessionSegs.length && ringHasKeys('assembly')) || sessionBusy || recPhase === 'recording'; }
  function renderModeUI() {
    const mode = getRecMode();
    const m = document.getElementById('modeMulti'), sg = document.getElementById('modeSingle');
    if (m) m.classList.toggle('active', mode === 'multi');
    if (sg) sg.classList.toggle('active', mode === 'single');
    const hint = document.getElementById('modeHint');
    if (hint) hint.textContent = mode === 'multi'
      ? 'each recording is added below the last, tap MULTIPLE again to start fresh'
      : 'each recording replaces the text, tap SINGLE again to start fresh';
  }
  function updateSessionLine() {
    const el = document.getElementById('sessionLine'); if (!el) return;
    if (!sessionSegs.length) { el.textContent = 'session empty'; return; }
    const words = sessionTranscript ? sessionTranscript.trim().split(/\s+/).filter(Boolean).length : 0;
    el.textContent = 'session  \u00B7  ' + sessionSegs.length + ' part' + (sessionSegs.length > 1 ? 's' : '') +
      '  \u00B7  ' + fmtDuration(sessionDurationMs) + '  \u00B7  ' + words + ' words';
  }

  // start a fresh segment recorder on the existing mic stream
  function startSegment() {
    currentChunks = [];
    seqInSeg = 0;
    mediaRecorder = new MediaRecorder(recStream, { mimeType: recMime });
    mediaRecorder.ondataavailable = e => {
      if (!e.data || !e.data.size) return;
      currentChunks.push(e.data);
      if (recPhase === 'recording') tick(); // keep duration fresh even if the bg timer throttled
      liveAdd({ take: takeId, seg: segIndex, seq: seqInSeg++, ts: Date.now(), blob: e.data }).catch(() => {});
      writeTakeMeta();
    };
    mediaRecorder.onstop = () => finalizeSegment();
    mediaRecorder.start(TIMESLICE_MS);
  }

  // close the current segment into a complete file on disk, then act on what was pending
  function finalizeSegment() {
    const action = pendingFinalize; pendingFinalize = null;
    const blob = new Blob(currentChunks, { type: 'audio/webm' });
    currentChunks = [];
    if (action === 'cancel') { discardTake(); return; }
    const next = () => { if (action === 'stop') saveTakeToSession(); };
    if (blob.size > 0) {
      takeSegments.push(blob);
      const thisSeg = segIndex; segIndex++;
      writeTakeMeta();
      segAdd({ take: takeId, seq: thisSeg, blob, created: Date.now() })
        .then(() => liveClear()).catch(() => {})
        .then(next, next);
    } else {
      next();
    }
  }

  // ---- add the take that just finished to the running session, then transcribe it and append ----
  function saveTakeToSession() {
    if (stitching) return;
    stitching = true;
    if (recStream) { try { recStream.getTracks().forEach(t => t.stop()); } catch (e) {} recStream = null; }

    const finish = (segs) => {
      const fresh = (segs || []).filter(b => b && b.size);
      const done = () => {
        liveClear().catch(() => {}); segClear().catch(() => {}); clearTakeMeta();
        elapsedMs = 0; recClock.innerHTML = fmtClock(0);
        takeSegments = [];
        stitching = false;
      };
      if (fresh.length === 0) { setRecStatus('nothing was recorded', 'err'); done(); return; }

      sessionSegs = sessionSegs.concat(fresh);
      sessionDurationMs += finalDurationMs;

      const stamp = new Date();
      if (!sessionName) sessionName = 'session_' + stamp.toISOString().replace(/[:.]/g, '-').slice(0, 19) + '.webm';

      const afterSave = () => {
        const totalSize = sessionSegs.reduce((sum, b) => sum + b.size, 0);
        setRecStatus('part ' + sessionSegs.length + ' saved  \u00B7  session ' + fmtDuration(sessionDurationMs) + '  \u00B7  ' + fmtMB(totalSize), 'ok');
        updateSessionLine(); updateRecTranscribeState();
        renderArchive();
        done();
        autoTranscribeParts(fresh);           // transcription starts on its own, no button needed
      };

      if (sessionRecId === null) {
        dbAdd({ name: sessionName, created: stamp.getTime(), durationMs: Math.round(sessionDurationMs), segments: sessionSegs.slice(), transcript: '' })
          .then(id => { sessionRecId = id; afterSave(); })
          .catch(e => { setRecStatus('saving to archive failed: ' + e, 'err'); done(); });
      } else {
        dbGet(sessionRecId).then(rec => {
          if (!rec) { sessionRecId = null; return; }
          rec.segments = sessionSegs.slice();
          rec.durationMs = Math.round(sessionDurationMs);
          return dbUpdate(rec);
        }).then(afterSave).catch(e => { setRecStatus('updating the archive failed: ' + e, 'err'); done(); });
      }
    };

    if (takeSegments.length > 0) finish(takeSegments.slice());
    else segAll().then(rows => finish(rows.sort((a, b) => a.seq - b.seq).map(r => r.blob))).catch(() => finish([]));
  }

  // write whatever the session transcript currently is back into its archive entry
  function persistSessionTranscript() {
    if (sessionRecId === null) return Promise.resolve();
    return dbGet(sessionRecId).then(rec => {
      if (!rec) return;
      rec.transcript = sessionTranscript;
      rec.procSec = lastProcSec || rec.procSec || 0;
      return dbUpdate(rec);
    }).then(renderArchive).catch(() => {});
  }

  // rebuild from the slots, so parts always appear in the order they were recorded,
  // even if a later part comes back from the server before an earlier one
  function rebuildSessionTranscript() {
    sessionTranscript = sessionParts.map(p => (p.text || '').trim()).filter(Boolean).join('\n\n');
    transcriptEl.value = sessionTranscript;
    updateSessionLine();
    persistSessionTranscript();
  }

  // in single mode a new recording starts its own session, so the old text goes away
  function beginSingleIfNeeded() {
    if (getRecMode() !== 'single') return;
    if (sessionRecId === null && !sessionSegs.length && !sessionTranscript) return; // already clean
    resetSession('single message mode, starting a fresh message');
  }

  // close the current session and clear the workspace, the finished one stays in the archive
  function resetSession(message) {
    const closingId = sessionRecId;
    const hadText = !!sessionTranscript.trim();
    if (closingId !== null && hadText) summarizeSessionById(closingId, sessionTranscript, setRecStatus);
    sessionRecId = null; sessionSegs = []; sessionTranscript = ''; sessionDurationMs = 0; sessionName = '';
    sessionParts = []; sessionPending = 0; sessionBusy = false;
    // a transcription already running is left to finish, its text goes to the entry it
    // belongs to instead of being lost, the generation guard keeps it out of the new session
    sessionGen++;
    takeSegments = []; finalDurationMs = 0;
    transcriptEl.value = '';
    if (typeof transcriptCorr !== 'undefined' && transcriptCorr) transcriptCorr.value = '';
    elapsedMs = 0; recClock.innerHTML = fmtClock(0);
    updateSessionLine(); updateRecTranscribeState();
    if (message) setRecStatus(message, 'ok');
  }

  // transcribe only the parts that were just recorded, then append them to the session text
  function autoTranscribeParts(parts) {
    if (!parts.length) return;
    if (!ringHasKeys('assembly')) { setRecStatus('no assemblyai keys, cannot transcribe', 'err'); return; }
    const slot = { text: '' };
    sessionParts.push(slot);
    const partNo = sessionParts.length;
    const myGen = sessionGen, myRecId = sessionRecId;
    sessionPending++; sessionBusy = true; setToggleUI(); updateRecTranscribeState();
    runTranscriptionSession(parts, setRecStatus, (text) => {
      // the session was reset while this was in flight, so keep the text out of the new one
      if (myGen !== sessionGen) {
        if (text !== null && myRecId !== null) {
          dbGet(myRecId).then(rec => { if (rec && !rec.transcript) { rec.transcript = text; dbUpdate(rec).then(renderArchive); } }).catch(() => {});
        }
        return;
      }
      sessionPending = Math.max(0, sessionPending - 1); sessionBusy = sessionPending > 0;
      setToggleUI(); updateRecTranscribeState();
      if (text !== null) {
        slot.text = text;
        rebuildSessionTranscript();
        const word = getRecMode() === 'single' ? 'transcribed' : 'transcribed and appended';
        setRecStatus('part ' + partNo + ' ' + word + '  \u00B7  record again to add more', 'ok');
      }
    });
  }

  // start a brand new session, the finished one stays complete in the archive
  function startNewSession() {
    if (recPhase === 'recording') { setRecStatus('stop the recording first', 'err'); return; }
    const had = sessionRecId !== null;
    resetSession(had ? 'started fresh, the last one is in the archive' : 'started fresh');
  }

  function startRecording() {
    beginSingleIfNeeded();
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) { setRecStatus('mic needs https or localhost', 'err'); return; }
    if (stitching) return;
    navigator.mediaDevices.getUserMedia({ audio: true }).then(stream => {
      recStream = stream;
      takeId = Date.now();
      segIndex = 0;
      takeSegments = [];
      recMime = MediaRecorder.isTypeSupported('audio/webm;codecs=opus') ? 'audio/webm;codecs=opus' : 'audio/webm';
      elapsedMs = 0; recClock.innerHTML = fmtClock(0);
      Promise.all([liveClear(), segClear()]).catch(() => {}).then(() => {
        pendingFinalize = null;
        writeTakeMeta();
        startSegment(); startClock(); startScope(stream);
        requestWakeLock(); startKeepAlive();
        recPhase = 'recording'; setToggleUI();
        recState.textContent = 'RECORDING'; recState.className = 'rec-state live';
        updateCancelState();
        setRecStatus('recording, safe in the background');
      });
    }).catch(err => setRecStatus('microphone access denied or unavailable: ' + err.message, 'err'));
  }

  // press to record, press again to stop and transcribe
  function stopAndTranscribe() {
    if (recPhase !== 'recording') return;
    stopClock(); stopScope();
    finalDurationMs = elapsedMs; // captured before the counter is zeroed
    releaseWakeLock(); stopKeepAlive();
    recPhase = 'idle'; setToggleUI();
    recState.textContent = ''; recState.className = 'rec-state';
    setRecStatus('finishing this part...');
    activateTab('transcribe');   // jump to the text, the transcript appears here when it lands
    if (mediaRecorder) {
      pendingFinalize = 'stop';
      try { mediaRecorder.requestData(); } catch (e) {}
      try { mediaRecorder.stop(); } catch (e) {} // onstop -> finalizeSegment -> saveTakeToSession
      mediaRecorder = null;
    } else {
      saveTakeToSession();
    }
  }

  // throw the running take away, the session and everything already transcribed stays untouched
  function discardTake() {
    stopScope();
    if (recStream) { try { recStream.getTracks().forEach(t => t.stop()); } catch (e) {} recStream = null; }
    takeSegments = []; currentChunks = []; finalDurationMs = 0;
    liveClear().catch(() => {}); segClear().catch(() => {}); clearTakeMeta();
    elapsedMs = 0; recClock.innerHTML = fmtClock(0);
    stitching = false;
    setToggleUI(); updateSessionLine(); updateRecTranscribeState();
  }

  function cancelRecording() {
    stopClock(); stopScope();
    releaseWakeLock(); stopKeepAlive();
    recPhase = 'idle';
    recState.textContent = ''; recState.className = 'rec-state';
    if (mediaRecorder) {
      pendingFinalize = 'cancel';
      try { mediaRecorder.stop(); } catch (e) {} // onstop -> finalizeSegment -> discardTake
      mediaRecorder = null;
    } else {
      discardTake();
    }
    setRecStatus('recording canceled, nothing was saved', 'ok');
  }

  // cancel: while recording it throws the take away, while transcribing it stops the transcription
  recCancelBtn.addEventListener('click', () => {
    if (recPhase === 'recording') { cancelRecording(); return; }
    if (sessionPending > 0) {
      txCancelGen++;                 // every transcription in flight gives up at its next step
      sessionPending = 0; sessionBusy = false;
      setMeter('idle'); setToggleUI(); updateRecTranscribeState();
      setRecStatus('transcription canceled, the audio is still in the session', 'ok');
    }
  });

  // the mode row: pressing the other mode switches and keeps the text, pressing the
  // active mode again starts fresh, which is what the old NEW SESSION button did
  ['modeMulti', 'modeSingle'].forEach(id => {
    const btn = document.getElementById(id);
    if (!btn) return;
    btn.addEventListener('click', () => {
      const want = btn.dataset.mode;
      if (recPhase === 'recording') { setRecStatus('stop the recording first', 'err'); return; }
      if (want === getRecMode()) { startNewSession(); renderModeUI(); return; }
      localStorage.setItem('maha_rec_mode', want);
      renderModeUI();
      // switching mid session keeps whatever is already there, only what happens next changes
      setRecStatus(want === 'multi'
        ? 'multiple message mode, the next recording is added below'
        : 'single message mode, the next recording replaces the text', 'ok');
    });
  });

  // ---- background survival ----
  // when the page is hidden, force a flush so the live store is current, and re-grab the wake lock on return
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
      if (mediaRecorder && mediaRecorder.state === 'recording') { try { mediaRecorder.requestData(); } catch (e) {} }
    } else {
      if (recPhase === 'recording') { requestWakeLock(); if (keepAudioCtx && keepAudioCtx.state === 'suspended') keepAudioCtx.resume().catch(() => {}); }
    }
  });
  window.addEventListener('pagehide', () => {
    if (mediaRecorder && mediaRecorder.state === 'recording') { try { mediaRecorder.requestData(); } catch (e) {} }
  });
  // warn before leaving mid-recording
  window.addEventListener('beforeunload', (e) => {
    if (recPhase === 'recording' || sessionBusy) { e.preventDefault(); e.returnValue = ''; return ''; }
  });

  // ---- recover a whole session interrupted by an OS/browser kill ----
  function recoverInterrupted() {
    let meta = null;
    try { meta = JSON.parse(localStorage.getItem(TAKE_META_KEY) || 'null'); } catch (e) { meta = null; }
    Promise.all([segAll(), liveAll()]).then(([segRows, liveRows]) => {
      const segs = (segRows || []).sort((a, b) => a.seq - b.seq).map(r => r.blob).filter(b => b && b.size);
      // rebuild the segment that was still open when the kill happened, from its live chunks
      if (liveRows && liveRows.length) {
        liveRows.sort((a, b) => (a.seg - b.seg) || (a.seq - b.seq));
        const tail = new Blob(liveRows.map(c => c.blob), { type: 'audio/webm' });
        if (tail.size) segs.push(tail);
      }
      if (segs.length === 0) { if (meta) clearTakeMeta(); return; }
      const stamp = new Date();
      const name = 'recovered_' + stamp.toISOString().replace(/[:.]/g, '-').slice(0, 19) + '.webm';
      const durationMs = (meta && meta.elapsedMs) ? meta.elapsedMs : 0;
      dbAdd({ name, created: stamp.getTime(), durationMs: Math.round(durationMs), segments: segs, transcript: '' })
        .then((id) => {
          // adopt it as the current session, so recording can carry straight on from where it died
          sessionRecId = id; sessionSegs = segs.slice(); sessionName = name;
          sessionDurationMs = Math.round(durationMs); sessionTranscript = ''; sessionParts = [];
          updateSessionLine(); updateRecTranscribeState();
          liveClear().catch(() => {}); segClear().catch(() => {}); clearTakeMeta();
          renderArchive();
          const totalSize = segs.reduce((s, b) => s + b.size, 0);
          setRecStatus('recovered an interrupted session  \u00B7  ' + segs.length + ' segment(s)  \u00B7  ' + fmtMB(totalSize), 'ok');
        })
        .catch(() => {});
    }).catch(() => {});
  }
  recoverInterrupted();

  function slugify(title) {
    return (title || 'recording').trim().replace(/[^\w\u00C0-\u024F ]+/g, '').replace(/\s+/g, '_').slice(0, 60);
  }

  function summarizeAndStore(recName, text, statusFn) {
    dbAll().then(list => {
      const rec = list.find(r => r.name === recName);
      if (!rec) return;
      rec.transcript = text;
      rec.procSec = lastProcSec || rec.procSec || 0;
      dbUpdate(rec).then(renderArchive);
      groqSummarize(text).then(sum => {
        if (!sum) { statusFn('archived, summary failed', 'ok'); return; }
        rec.title = sum.title || '';
        rec.summary = sum.summary || '';
        if (rec.title) rec.name = slugify(rec.title) + '.webm';
        dbUpdate(rec).then(renderArchive);
        statusFn('archived as "' + (rec.title || rec.name) + '"', 'ok');
      });
    });
  }

  // title and summary for a session, looked up by id because the name changes when it gets titled
  function summarizeSessionById(id, text, statusFn) {
    dbGet(id).then(rec => {
      if (!rec) return;
      rec.transcript = text;
      rec.procSec = lastProcSec || rec.procSec || 0;
      dbUpdate(rec).then(renderArchive);
      groqSummarize(text).then(sum => {
        if (!sum) { statusFn('archived, summary failed', 'ok'); return; }
        rec.title = sum.title || '';
        rec.summary = sum.summary || '';
        if (rec.title) rec.name = slugify(rec.title) + '.webm';
        dbUpdate(rec).then(renderArchive);
        statusFn('archived as "' + (rec.title || rec.name) + '"', 'ok');
      });
    });
  }

  // redo the whole session from its audio, every part, replacing the appended text
  recTranscribeBtn.addEventListener('click', () => {
    if (!sessionSegs.length || sessionBusy || recPhase === 'recording') return;
    sessionPending++; sessionBusy = true; setToggleUI(); updateRecTranscribeState();
    runTranscriptionSession(sessionSegs, setRecStatus, (text) => {
      sessionPending = Math.max(0, sessionPending - 1); sessionBusy = sessionPending > 0; setToggleUI(); updateRecTranscribeState();
      if (text !== null) {
        sessionParts = [{ text: (text || '').trim() }];
        rebuildSessionTranscript();
        setRecStatus('whole session transcribed  \u00B7  ' + sessionSegs.length + ' part(s)', 'ok');
      }
    });
  });

  // ---- archive ----
  const arhList = document.getElementById('arhList');
  const arhStatus = document.getElementById('arhStatus');
  function setArhStatus(text, kind) { arhStatus.textContent = text; arhStatus.className = 'status' + (kind ? ' ' + kind : ''); }

  // a record may hold several segment files, or a single legacy blob
  function recSegments(rec) { return (rec.segments && rec.segments.length) ? rec.segments : (rec.blob ? [rec.blob] : []); }
  function recSize(rec) { return recSegments(rec).reduce((s, b) => s + (b ? b.size : 0), 0); }
  function playSegments(container, segs) {
    const existing = container.querySelector('audio');
    if (existing) { existing.remove(); return; }
    if (!segs.length) return;
    const audio = document.createElement('audio');
    audio.controls = true; audio.style.width = '100%'; audio.style.marginTop = '8px';
    let idx = 0;
    const load = () => { audio.src = URL.createObjectURL(segs[idx]); audio.play().catch(() => {}); };
    audio.addEventListener('ended', () => { idx++; if (idx < segs.length) load(); });
    container.appendChild(audio); load();
  }

  function getArhLang() { return localStorage.getItem('maha_arh_lang') === 'en' ? 'en' : 'hr'; }
  function renderArchive() {
    dbAll().then(list => {
      list.sort((a, b) => b.created - a.created);
      arhList.innerHTML = '';
      if (list.length === 0) { arhList.innerHTML = '<div class="arh-empty">no recordings yet, use the REC tab</div>'; return; }
      const langBar = document.createElement('div');
      langBar.className = 'row arh-lang-row';
      const al = getArhLang();
      langBar.innerHTML =
        '<button type="button" class="lang-btn arh-lang' + (al === 'hr' ? ' active' : '') + '" data-lang="hr">HR</button>' +
        '<button type="button" class="lang-btn arh-lang' + (al === 'en' ? ' active' : '') + '" data-lang="en">EN</button>';
      Array.from(langBar.querySelectorAll('.arh-lang')).forEach(b => b.addEventListener('click', () => {
        localStorage.setItem('maha_arh_lang', b.dataset.lang); renderArchive();
      }));
      arhList.appendChild(langBar);
      list.forEach(rec => {
        const div = document.createElement('div');
        div.className = 'arh-item';
        const dur = rec.durationMs ? fmtDuration(rec.durationMs) + ', ' : '';
        const segs = recSegments(rec);
        const size = segs.length ? fmtMB(recSize(rec)) : '';
        const segCount = segs.length > 1 ? ', ' + segs.length + ' segments' : '';
        const score = rec.procSec ? ', score ' + Number(rec.procSec).toFixed(1) + 's' : '';
        const hasT = rec.transcript ? ', transcribed' : '';
        const shown = rec.title ? rec.title : rec.name;
        const tBtn = rec.transcript ? '<button class="small-btn" data-act="copy">copy</button><button class="small-btn" data-act="text">transcript</button><button class="small-btn" data-act="exptxt">export txt</button>' : '';
        div.innerHTML =
          '<div class="arh-name">' + shown + '</div>' +
          '<div class="arh-meta">' + rec.name + '<br>' + new Date(rec.created).toLocaleString() + ', ' + dur + size + segCount + score + hasT + '</div>' +
          (rec.summary ? '<div class="arh-meta">' + rec.summary + '</div>' : '') +
          '<div class="arh-actions">' +
          '<button class="small-btn" data-act="play">play</button>' + tBtn +
          '<button class="small-btn" data-act="retr">retranscribe</button>' +
          '<button class="small-btn" data-act="export">export audio</button>' +
          '<button class="small-btn danger" data-act="del">delete</button>' +
          '</div>';
        div.querySelector('[data-act=play]').addEventListener('click', () => {
          playSegments(div, recSegments(rec));
        });
        const copyRecBtn = div.querySelector('[data-act=copy]');
        if (copyRecBtn) copyRecBtn.addEventListener('click', () => {
          const t = rec.transcript || '';
          const done = () => { copyRecBtn.textContent = 'copied'; setTimeout(() => { copyRecBtn.textContent = 'copy'; }, 1400); };
          if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(t).then(done).catch(() => fallbackCopy(t, done));
          else fallbackCopy(t, done);
        });
        const textBtn = div.querySelector('[data-act=text]');
        if (textBtn) textBtn.addEventListener('click', () => {
          transcriptEl.value = rec.transcript || '';
          tabBtns.find(b => b.dataset.tab === 'transcribe').click();
          setStatus('loaded', 'ok');
        });
        const expTxtBtn = div.querySelector('[data-act=exptxt]');
        if (expTxtBtn) expTxtBtn.addEventListener('click', () => {
          const blob = new Blob([rec.transcript || ''], { type: 'text/plain' });
          const a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = rec.name.replace(/\.webm$/i, '') + '.txt';
          document.body.appendChild(a); a.click(); a.remove();
          setArhStatus('exported txt', 'ok');
        });
        div.querySelector('[data-act=retr]').addEventListener('click', () => {
          const segs = recSegments(rec);
          const al = getArhLang();
          forcedLang = al; // archive retranscribe always uses this language
          setArhStatus('retranscribing ' + rec.name + ' in ' + al.toUpperCase() + ' via assemblyai' + (segs.length > 1 ? ' (' + segs.length + ' segments)' : ''));
          runTranscriptionSession(segs, setArhStatus, (text) => {
            forcedLang = null;
            if (text !== null) {
              transcriptEl.value = text;
              summarizeAndStore(rec.name, text, setArhStatus);
              tabBtns.find(b => b.dataset.tab === 'transcribe').click();
            }
          });
        });
        div.querySelector('[data-act=export]').addEventListener('click', () => {
          const segs = recSegments(rec);
          const base = rec.name.replace(/\.webm$/i, '');
          segs.forEach((b, i) => {
            const a = document.createElement('a');
            a.href = URL.createObjectURL(b);
            a.download = segs.length > 1 ? base + '_' + (i + 1) + '.webm' : rec.name;
            document.body.appendChild(a); a.click(); a.remove();
          });
          setArhStatus(segs.length > 1 ? 'exported ' + segs.length + ' segment files' : 'exported', 'ok');
        });
        div.querySelector('[data-act=del]').addEventListener('click', () => {
          if (!confirm('delete ' + rec.name + '?')) return;
          dbDelete(rec.id).then(() => { renderArchive(); setArhStatus('deleted ' + rec.name, 'ok'); });
        });
        arhList.appendChild(div);
      });
    }).catch(e => setArhStatus('could not open the archive: ' + e, 'err'));
  }

  document.getElementById('arhDeleteAllBtn').addEventListener('click', () => {
    if (!confirm('delete the WHOLE archive, every recording and transcript?')) return;
    dbAll().then(list => Promise.all(list.map(r => dbDelete(r.id)))).then(() => {
      renderArchive(); setArhStatus('archive emptied', 'ok');
    });
  });

  // ---- shared round copy button wiring ----
  function wireCopy(btn, getText) {
    if (!btn) return;
    btn.addEventListener('click', () => {
      const t = getText(); if (!t) return;
      const done = () => { const old = btn.textContent; btn.textContent = 'copied'; setTimeout(() => { btn.textContent = old; }, 1400); };
      if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(t).then(done).catch(() => fallbackCopy(t, done));
      else fallbackCopy(t, done);
    });
  }

  // ---- GRAMMAR on the transcribe tab, corrects the transcript into the second box ----
  const grammarBtn = document.getElementById('grammarBtn');
  const grammarStatus = document.getElementById('grammarStatus');
  const transcriptCorr = document.getElementById('transcriptCorr');
  function setGrammarStatus(t, k) { grammarStatus.textContent = t; grammarStatus.className = 'status' + (k ? ' ' + k : ''); }
  const reshapeBtn = document.getElementById('reshapeBtn');
  function getCorrProvider() { return localStorage.getItem('maha_corr_provider') === 'gemini' ? 'gemini' : 'claude'; }
  function getClaudeEffort() { const e = localStorage.getItem('maha_claude_effort'); return ['low', 'medium', 'high'].includes(e) ? e : 'low'; }
  // ONE ENGINE. Upstream this chose between Claude and Gemini, then a model
  // within whichever was chosen, and a spend budget for one of them. All of
  // that is gone: the server picks from the models the ring can actually reach
  // and answers on /api/rewrite. A model list in a settings panel is a list
  // that goes stale, and a dated model name is a time bomb that fails before
  // the request runs.
  async function runCorrection(kind) {
    const text = (transcriptEl.value || '').trim();
    if (!text) { setGrammarStatus('the transcript box is empty', 'err'); return; }
    const verb = kind === 'grammar' ? 'correcting' : 're-shaping';
    grammarBtn.disabled = true; reshapeBtn.disabled = true; setMeter('busy');
    setGrammarStatus(verb + '\u2026');
    try {
      const r = await fetch('/api/rewrite', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-Gtt-Local': '1' },
        body: JSON.stringify({ kind: kind, text: text.slice(0, 60000) })
      });
      const j = await r.json();
      if (j.ok) {
        transcriptCorr.value = j.text;
        setMeter('ok');
        setGrammarStatus('done  \u00b7  ' + j.model + ' on [' + j.key + ']', 'ok');
        bumpUsage('corr');
      } else {
        setMeter('err');
        setGrammarStatus(j.error || 'failed', 'err');
      }
    } catch (e) {
      setMeter('err'); setGrammarStatus(e.message, 'err');
    }
    grammarBtn.disabled = false; reshapeBtn.disabled = false;
    setTimeout(() => setMeter('idle'), 1600);
  }
  grammarBtn.addEventListener('click', () => runCorrection('grammar'));
  reshapeBtn.addEventListener('click', () => runCorrection('reshape'));

  // ===== Claude API integration =====
  const CLAUDE_MODELS = {
    'claude-opus-4-8':           { name: 'Opus',   inP: 5, outP: 25 },
    'claude-sonnet-5':           { name: 'Sonnet', inP: 2, outP: 10 }, // intro rate thru 2026-08-31, then 3/15
    'claude-haiku-4-5-20251001': { name: 'Haiku',  inP: 1, outP: 5 }
  };
  const CLAUDE_EFFORTS = [
    { id: 'low',    label: 'Low',    budget: 0 },
    { id: 'medium', label: 'Medium', budget: 2048 },
    { id: 'high',   label: 'High',   budget: 6144 }
  ];
  let claudeSpent = 0;
  function getClaudeModel() { const m = localStorage.getItem('maha_claude_model'); return CLAUDE_MODELS[m] ? m : 'claude-opus-4-8'; }
  function getClaudeBudget() { const b = parseFloat(localStorage.getItem('maha_claude_budget')); return (isFinite(b) && b > 0) ? b : 5; }
  function setClaudeStatus(t, k) { const el = document.getElementById('claudeStatus'); if (el) { el.textContent = t; el.className = 'status' + (k ? ' ' + k : ''); } }
  function updateClaudeUsage() {
    const el = document.getElementById('claudeUsage'); if (!el) return;
    const left = getClaudeBudget() - claudeSpent;
    el.textContent = 'Claude API  \u00b7  spent $' + claudeSpent.toFixed(4) + '  \u00b7  left $' + left.toFixed(4);
  }
  function updateClaudeButtons() {
    const name = CLAUDE_MODELS[getClaudeModel()].name;
    CLAUDE_EFFORTS.forEach(e => { const b = document.getElementById('claude-' + e.id); if (b) b.textContent = name + ' ' + e.label; });
  }
  async function claudeGenerate(prompt, effortId, statusFn) {
    const ring = loadRing('claude');
    if (!ring.keys.length) { if (statusFn) statusFn('no claude api key, add one in settings', 'err'); return null; }
    const model = getClaudeModel();
    const eff = CLAUDE_EFFORTS.find(e => e.id === effortId) || CLAUDE_EFFORTS[0];
    const body = { model: model, max_tokens: eff.budget ? eff.budget + 4096 : 4096, messages: [{ role: 'user', content: prompt }] };
    if (eff.budget) body.thinking = { type: 'enabled', budget_tokens: eff.budget };
    const { result, err } = await KR.rotate(ring, async (key) => {
      try {
        const res = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: {
            'content-type': 'application/json',
            'x-api-key': key,
            'anthropic-version': '2023-06-01',
            'anthropic-dangerous-direct-browser-access': 'true'
          },
          body: JSON.stringify(body)
        });
        if (res.ok) {
          const data = await res.json();
          const text = (data.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
          const u = data.usage || {};
          const m = CLAUDE_MODELS[model];
          const cost = ((u.input_tokens || 0) / 1e6) * m.inP + ((u.output_tokens || 0) / 1e6) * m.outP;
          return { kind: 'ok', result: { text: text, cost: cost, usage: u } };
        }
        const bodyText = await res.text().catch(() => '');
        return krClassify(res.status, bodyText, res.headers);
      } catch (e) { return { kind: 'soft', err: 'network error: ' + e.message }; }
    });
    saveRing('claude', ring);
    if (result) { claudeSpent += result.cost; updateClaudeUsage(); }
    else if (statusFn) statusFn('claude: ' + (err || 'failed'), 'err');
    return result;
  }
  function renderClaudeEffort() {
    const cur = getClaudeEffort();
    CLAUDE_EFFORTS.forEach(e => { const b = document.getElementById('claude-' + e.id); if (b) b.classList.toggle('active', e.id === cur); });
    // the engagement level only affects Claude, fade the row when Gemini is the provider
    const row = document.getElementById('claudeRow');
    const lbl = document.getElementById('claudeLevelLabel');
    const dim = getCorrProvider() !== 'claude';
    if (row) row.style.opacity = dim ? '0.4' : '1';
    if (lbl) lbl.style.opacity = dim ? '0.4' : '1';
  }
  CLAUDE_EFFORTS.forEach(e => {
    const b = document.getElementById('claude-' + e.id);
    if (b) b.addEventListener('click', () => { localStorage.setItem('maha_claude_effort', e.id); renderClaudeEffort(); });
  });
  function renderClaudeModels() {
    const wrap = document.getElementById('claudeModelList'); if (!wrap) return;
    const cur = getClaudeModel();
    wrap.innerHTML = Object.keys(CLAUDE_MODELS).map(id =>
      '<button type="button" class="lang-btn claude-model' + (id === cur ? ' active' : '') + '" data-model="' + id + '">' + CLAUDE_MODELS[id].name + '</button>'
    ).join('');
    Array.from(wrap.querySelectorAll('.claude-model')).forEach(b => b.addEventListener('click', () => {
      localStorage.setItem('maha_claude_model', b.dataset.model);
      renderClaudeModels(); updateClaudeButtons(); updateClaudeUsage();
    }));
  }
  function renderCorrProvider() {
    const wrap = document.getElementById('corrProviderList'); if (!wrap) return;
    const cur = getCorrProvider();
    const opts = [{ id: 'claude', label: 'CLAUDE' }, { id: 'gemini', label: 'GEMINI' }];
    wrap.innerHTML = opts.map(o =>
      '<button type="button" class="big-choice' + (o.id === cur ? ' active' : '') + '" data-prov="' + o.id + '">' + o.label + '</button>'
    ).join('');
    Array.from(wrap.querySelectorAll('.big-choice')).forEach(b => b.addEventListener('click', () => {
      localStorage.setItem('maha_corr_provider', b.dataset.prov);
      renderCorrProvider(); renderClaudeEffort();
    }));
  }
  (function initClaude() {
    renderClaudeModels(); updateClaudeButtons(); updateClaudeUsage(); renderClaudeEffort(); renderCorrProvider();
    const budget = document.getElementById('claudeBudget');
    if (budget) { budget.value = getClaudeBudget(); budget.addEventListener('change', () => { const v = parseFloat(budget.value); if (isFinite(v) && v > 0) localStorage.setItem('maha_claude_budget', String(v)); updateClaudeUsage(); }); }
  })();
  wireCopy(document.getElementById('copyCorrBtn'), () => transcriptCorr.value);

  // ---- QUICK tab, walkie talkie, one button, records then auto sends to Whisper ----

  // ---- TRANSLATE tab, Gemini ----
  const transSrc = document.getElementById('transSrc');
  const transOut = document.getElementById('transOut');
  const transStatus = document.getElementById('transStatus');
  const translateBtn = document.getElementById('translateBtn');
  function setTransStatus(t, k) { transStatus.textContent = t; transStatus.className = 'status' + (k ? ' ' + k : ''); }

  function makeLangGroup(cls, storeKey, def) {
    const btns = Array.from(document.querySelectorAll('.' + cls));
    const get = () => localStorage.getItem(storeKey) || def;
    const apply = () => btns.forEach(b => b.classList.toggle('active', b.dataset.lang === get()));
    btns.forEach(b => b.addEventListener('click', () => { localStorage.setItem(storeKey, b.dataset.lang); apply(); }));
    apply();
    return get;
  }
  const getTransFrom = makeLangGroup('tl-from', 'maha_trans_from', 'auto');
  const getTransTo = makeLangGroup('tl-to', 'maha_trans_to', 'en');

  const transModelList = document.getElementById('transModelList');
  function getTransModel() { const m = localStorage.getItem('maha_trans_model'); return CORR_MODELS.some(x => x.id === m) ? m : 'gemini-2.5-flash'; }
  function renderTransModels() {
    const cur = getTransModel();
    transModelList.innerHTML = CORR_MODELS.map(m => '<button type="button" class="lang-btn tl-model' + (m.id === cur ? ' active' : '') + '" data-model="' + m.id + '">' + m.label + '</button>').join('');
    Array.from(transModelList.querySelectorAll('.tl-model')).forEach(b => b.addEventListener('click', () => { localStorage.setItem('maha_trans_model', b.dataset.model); renderTransModels(); }));
  }
  renderTransModels();

  function langName(c) { return c === 'hr' ? 'Croatian' : c === 'en' ? 'English' : 'auto'; }
  translateBtn.addEventListener('click', async () => {
    const text = transSrc.value.trim();
    if (!text) { setTransStatus('nothing to translate', 'err'); return; }
    if (!ringHasKeys('gemini')) { setTransStatus('no gemini keys', 'err'); return; }
    const from = getTransFrom(), to = getTransTo();
    const src = from === 'auto' ? 'the detected source language' : langName(from);
    let tgt;
    if (to === 'auto') tgt = (from === 'en') ? 'Croatian' : 'English';
    else tgt = langName(to);
    translateBtn.disabled = true; setMeter('busy');
    const model = getTransModel();
    setTransStatus('translating to ' + tgt + ' with ' + model);
    const prompt = 'Translate the following text from ' + src + ' to ' + tgt + '. Return only the translation, with no notes and no quotes, and keep it natural.\n\n' + text.slice(0, 60000);
    const res = await geminiGenerate(prompt, model, setTransStatus);
    if (res) { transOut.value = res.text; setMeter('ok'); setTransStatus('translated to ' + tgt + ', key ' + maskKey(res.key), 'ok'); }
    else setMeter('err');
    translateBtn.disabled = false; setTimeout(() => setMeter('idle'), 1600);
  });
  wireCopy(document.getElementById('copyTransBtn'), () => transOut.value);

  // ---- paste and clear toolbars above every text box ----
  Array.from(document.querySelectorAll('[data-boxact]')).forEach(btn => {
    const box = document.getElementById(btn.dataset.target);
    const act = btn.dataset.boxact;
    btn.addEventListener('click', async () => {
      if (!box) return;
      if (act === 'clear') { box.value = ''; box.focus(); return; }
      try {
        const t = await navigator.clipboard.readText();
        box.value = t; box.focus();
      } catch (e) {
        box.focus(); // clipboard read blocked, focus so the user can long press paste
      }
    });
  });

  // initial UI state, so the buttons and session line are correct before anything is pressed
  renderModeUI();
  setToggleUI();
  drawScopeIdle();
  updateSessionLine();
  updateRecTranscribeState();
  renderArchive();
})();
</script>
</body>
</html>

GTT_TRANSCRIBE_EOF
mv -f "$APPHOME/transcribe.html.new" "$APPHOME/transcribe.html"
chmod 644 "$APPHOME/transcribe.html"
done_

# ---------------------------------------------------------------- commands
# RENAME, NEVER TRUNCATE. gtt-update runs this installer, so while these lines
# execute the old gtt-update is still open and bash is still reading it. A
# plain `cat >` over that file truncates what the running shell is reading and
# it carries on at the old byte offset into whatever is there now. Small files
# survive by luck. Luck is not a mechanism. So each command is written beside
# its own name and renamed over the top: the rename swaps the directory entry,
# the running shell keeps its open file and reads to the end undisturbed, and
# nothing half written is ever reachable under the real name.
rm -f "$BIN/gtt.new" "$BIN/gtts.new" "$BIN/gtt-update.new"

step "gtt"
cat > "$BIN/gtt.new" <<GTT_CMD_EOF
#!/usr/bin/env bash
# gtt - Google TTS and STT $GTT_VERSION
APP="$APP"
PY="$PY"
KEYS="$KEYS"
OUT="$OUT"
if [ -t 1 ]; then AM="\033[38;5;214m"; SAND="\033[38;5;223m"; DIM="\033[0;90m"; OFF="\033[0m"
else AM=""; SAND=""; DIM=""; OFF=""; fi
case "\${1:-run}" in
  run|"") MENU=0 ;;
  menu)   MENU=1 ;;
  test)   exec "\$PY" "\$APP" test ;;
  keys)   exec \${EDITOR:-nano} "\$KEYS" ;;
  import) shift; exec "\$PY" "\$APP" import "\$@" ;;
  out)    exec ls -la "\$OUT" ;;
  update) exec gtt-update ;;
  *)      MENU=0 ;;
esac

panel() {
  printf "\n"
  printf "  \${AM}GOOGLE TTS AND STT\${OFF} $GTT_VERSION\n"
  printf "  +---------------------+---------------------+\n"
  printf "  |1 Speak              |2 Listen             |\n"
  printf "  |  text becomes audio |  audio becomes text |\n"
  printf "  |  thirty voices      |  any format ffmpeg  |\n"
  printf "  +---------------------+---------------------+\n"
  printf "  |3 Keys               |4 free               |\n"
  printf "  |  import and test    |                     |\n"
  printf "  |  what is left today |  room for a fourth  |\n"
  printf "  +---------------------+---------------------+\n"
  printf "  \${DIM}all four are tabs on the page, and the page is where\n"
  printf "  everything is done. This is the picture of it.\${OFF}\n"
  printf "  \${DIM}R un  T est  K eys  O utput  U pdate  I mport  Q uit\n"
  printf "  are the keys, and each one spells its own word.\${OFF}\n"
}

if [ "\$MENU" = "1" ]; then
  while true; do
    panel
    # EVERY LABEL IS SPELLED BY ITS OWN KEY. R un, T est, K eys, O utput,
    # U pdate, I mport, Q uit. A key whose letter does not begin its word has
    # to be read rather than recognised, and this row is meant to be
    # recognised. The numbers still work because fingers that learned them in
    # v6 should not be punished, but they are not drawn any more: two labels
    # for one action is two things to read.
    # Padded on the plain text, the colour wrapped around the letter only.
    # printf counts the bytes of an escape sequence as width, so a coloured
    # string handed to %-10s comes out short by the length of its escapes and
    # every column after it walks left. Four cells of ten, then three.
    printf "\n  \${AM}R\${OFF} un       \${AM}T\${OFF} est      \${AM}K\${OFF} eys      \${AM}O\${OFF} utput\n"
    printf "  \${AM}U\${OFF} pdate    \${AM}I\${OFF} mport    \${AM}Q\${OFF} uit\n\n  > "
    read -rsn1 k; printf "\n\n"
    case "\$k" in
      r|R|1) "\$PY" "\$APP" ;;
      t|T|2) "\$PY" "\$APP" test ;;
      k|K|3) \${EDITOR:-nano} "\$KEYS" ;;
      o|O|4) ls -la "\$OUT" ;;
      u|U|5) gtt-update ;;
      i|I|6) printf "  path to the key file: "; read -r f; [ -n "\$f" ] && "\$PY" "\$APP" import "\$f" ;;
      q|Q|0) exit 0 ;;
    esac
  done
fi

# The plain word starts the app and lets the app open the browser. Everything
# is done on the page, keys included, so there is nothing to choose here first.
panel
exec "\$PY" "\$APP"
GTT_CMD_EOF
chmod +x "$BIN/gtt.new"
mv -f "$BIN/gtt.new" "$BIN/gtt"
done_

step "gtt-update"
cat > "$BIN/gtt-update.new" <<GTT_UPD_EOF
#!/usr/bin/env bash
# gtt-update - fetch the newest installer and run it.
# This file is rewritten by the installer it runs. That is safe only because
# the installer renames over it instead of truncating it. Do not "simplify"
# that into a cat.
set -u
REPO="$GTT_REPO"
TMP="\$(mktemp -d)"
trap 'rm -rf "\$TMP"' EXIT
if [ -t 1 ]; then AM="\033[38;5;214m"; BAD="\033[1;31m"; DIM="\033[0;90m"; OFF="\033[0m"
else AM=""; BAD=""; DIM=""; OFF=""; fi
printf "\n  \${AM}gtt-update\${OFF}  installed $GTT_VERSION\n\n"
# raw first, the API only if raw has nothing. The API is sixty an hour per
# address to an unauthenticated caller, and on mobile data that address is the
# carrier's, not yours.
NAME="\$(curl -fsSL "https://raw.githubusercontent.com/\$REPO/main/LATEST" 2>/dev/null | tr -d '\r\n ')"
if [ -z "\$NAME" ]; then
  LIST="\$(curl -fsSL "https://api.github.com/repos/\$REPO/contents/" 2>/dev/null)" || true
  NAME="\$(printf '%s' "\$LIST" | grep -o '"name": *"[0-9]*-google-tts-stt-v[0-9]*\.sh"' \
    | sed 's/.*"\(.*\)"/\1/' | sort -t v -k2 -n | tail -1)"
fi
case "\$NAME" in
  [0-9]*-google-tts-stt-v[0-9]*.sh) : ;;
  *) printf "  \${BAD}cannot work out which installer is newest\${OFF}, nothing changed\n\n"; exit 1 ;;
esac
NEWV="v\${NAME##*-v}"; NEWV="\${NEWV%.sh}"
if [ "\$NEWV" = "$GTT_VERSION" ]; then
  printf "  already on \$NEWV, nothing to do\n\n"; exit 0
fi
printf "  \${AM}\$NEWV\${OFF} is out, fetching\n"
curl -fsSL "https://raw.githubusercontent.com/\$REPO/main/\$NAME" -o "\$TMP/\$NAME" || {
  printf "  \${BAD}download failed\${OFF}, nothing changed\n\n"; exit 1; }
bash "\$TMP/\$NAME" --verify >/dev/null 2>&1 || {
  printf "  \${BAD}the download is not whole\${OFF}, nothing changed\n\n"; exit 1; }
printf "  \${DIM}running \$NAME\${OFF}\n"
exec bash "\$TMP/\$NAME"
GTT_UPD_EOF
chmod +x "$BIN/gtt-update.new"
mv -f "$BIN/gtt-update.new" "$BIN/gtt-update"
done_

step "gtts"
# The app is called Google TTS and STT, so gtts is what the hand types. It was
# typed on the first day. A command that exists under one name and is reached
# for under another is a command with a bug in its name.
cat > "$BIN/gtts.new" <<GTTS_ALIAS_EOF
#!/usr/bin/env bash
# gtts - the same thing as gtt. Both names work; gtt is the shorter one.
exec "$BIN/gtt" "\$@"
GTTS_ALIAS_EOF
chmod +x "$BIN/gtts.new"
mv -f "$BIN/gtts.new" "$BIN/gtts"
done_

# ---------------------------------------------------------------- PATH
case ":$PATH:" in
  *":$BIN:"*) : ;;
  *)
    blank
    say "${WARN}$BIN is not on your PATH.${OFF} Add this to your shell rc:"
    say "${DIM}    export PATH=\"\$HOME/bin:\$PATH\"${OFF}"
    ;;
esac

# ---------------------------------------------------------------- keys in
# Done AFTER the app is written, because the app owns the parser. One parser,
# one merge, one place where a duplicate could be created and therefore one
# place where it is prevented.
if [ -n "$IMPORT" ]; then
  blank
  if [ -f "$IMPORT" ]; then
    say "${DIM}reading keys from $IMPORT${OFF}"
    "$PY" "$APP" import "$IMPORT"
  else
    say "${BAD}no file at $IMPORT${OFF}, nothing imported"
  fi
fi

# --------------------------------------------------------------- finished
blank
# INSTALLING DOES NOT SPEND YOUR KEYS. The tests are real calls to a real
# provider against a real ring, which is what makes them worth having and
# exactly why they must not run behind your back: a TTS account has ten
# requests a day, and an install that quietly takes a few of them has decided
# something on your behalf. Baba, 5.9.2026.
#
# `bash <installer> --test` still runs them, because asking for them is
# different from having them happen.
KEYCOUNT="$(grep -cE '^AQ\.[A-Za-z0-9_-]{20,}$' "$KEYS" 2>/dev/null || true)"
KEYCOUNT="$(printf '%s' "$KEYCOUNT" | tr -dc '0-9')"
[ -z "$KEYCOUNT" ] && KEYCOUNT=0
RC=0
if [ "$RUNTESTS" = "1" ]; then
  if [ "$KEYCOUNT" -lt 1 ]; then
    say "${WARN}--test was asked for, but the ring is empty.${OFF}"
  else
    say "${DIM}four tests, real keys, no mocks, because you asked${OFF}"
    blank
    "$PY" "$APP" test
    RC=$?
    blank
  fi
fi

say "${OK}installed${OFF} $GTT_VERSION"
if [ "$KEYCOUNT" -lt 1 ]; then
  blank
  say "${WARN}No keys yet.${OFF} Run ${SAND}gtt${OFF} — it opens the page, and the KEYS"
  say "tab has the file picker. That is where they go. Or from here:"
  say "  ${DIM}gtt import /sdcard/Download/your-keys.txt${OFF}"
fi
blank
say "  ${SAND}gtt${OFF}          starts it and opens the browser"
say "  ${DIM}gtts${OFF}         the same thing, for when that is what you type"
say "  ${DIM}gtt menu${OFF}     the panel, if you want it"
say "  ${DIM}gtt test${OFF}     the four tests, when YOU want them"
say "  ${SAND}gtt import F${OFF} add accounts from any file, without duplicating"
say "  ${SAND}gtt-update${OFF}   fetch the next version"
if [ "$RC" -ne 0 ]; then
  blank
  say "${BAD}a test failed.${OFF} The app is installed either way."
fi
blank
exit 0
